Delete From HELPBASE;
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/Urbanizzazione/OICalcoloContribT.aspx',
'In questa pagina vanno definiti i coefficienti dei parametri utilizzati nel calcolo.

In base alle differenti destinazioni d''uso che caratterizzano il singolo corpo da cubare, vengono presentati solamente i parametri relativi alla specifica situazione dell''immobile. E'' necessario selezionare, tramite i menu a tendina, i coefficienti per ogni parametro presentato. I parametri che possono essere visualizzati sono:
<b>Zone PRG:</b> defisce le zona in cui ricade l''immobile.
<b>Tipo intervento:</b> definisce il tipo di intervento che va ad essere effettuato sull''immbile.
<b>Indici territoriali:</b> definisce quale indice territoriale va applicato al caso specifico.

E'' necessario selezionare il pulsante <b>Procedi</b> per registrare gli inserimenti o le modifiche e generare conseguentemente il risultato del calcolo. Il risultato viene visualizzato in una tabella sottostante, la quale riporta l''ammontare delle superfici o dei volumi, il costo unitario, e gli importi delle differenti tipologie di oneri.

Per modificare i coefficienti del calcolo utilizzare il pulsante <b>Modifica</b>.

E'' inoltre possibile modificare unilateralmente il costo unitario (di urbanizzaione primaria o secondaria) modificando il valore nei relativi campi  e selezionando poi il pulsante <b>Salva</b>, forzando così il sistema a non tenere conto dei coefficienti impostati per il calcolo.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OConfigurazione.aspx',
'In questa pagina è possibile configurare alcuni parametri di base necessari alla registrazione del costo unitario degli Oneri di Urbanizzazione.
I primi due campi sono opzionali e vengono impostati solamente nel caso in cui il comune utilizzi tali parametri nel calcolo degli oneri. 

<b>Tipo area ZTO:</b> consente di inserire una prima tipologia di Area Omogenea da considerare nel calcolo, qualora tale parametro venga utilizzato nel calcolo dall''amministrazione. Tutti gli elementi (zonizzazioni) contenuti nel Tipo Area Omogenea specificato, vengono successivamente utilizzati nella definizione dei singoli costi unitari all''interno della funzione listino. I tipi Area Omogenea vengono definiti in Archivi>modulo>Tabelle>Tipo Zona; gli elementi per ogni Tipo Zona Omogenea vengono definiti in Archivi>modulo>Tabelle>Zonizzazione.
<i>Un tipo zona potrebbe essere ad esempio "Aree Cittadine" contenente le zonizzazioni "Area Urbana", "Periferia", "Area Collinare"</i>

<b>Tipo area PRG:</b> consente di inserire una seconda tipologia di Area Omogenea da considerare nel calcolo, qualora tale parametro venga utilizzato nel calcolo dalla singola amministrazione. I Tipi Area PRG e relativi elementi vengono definiti all''interno delle Tabelle come sopra illustrato.
<i>Il campo viene tipicamente utilizzato per definire le zone di PRG quando queste vengano utilizzate come parametro per il calcolo degli oneri</i>

<b>Unità di misura in mq</b> e <b>Unità di misura in mc:</b> vanno specificati i codici che rappresentano le unità di misura per il calcolo delle superfici o dei volumi.

<b>Imputare superfici/cubature</b>: consente di definire se la modalità di imputazione delle superfici o dei volumi sia generica o dettagliata; se spuntato, l''operatore, durante la fase di calcolo degl oneri, avrà la possibilità di imputare le misure delle superfici o dei volumi di dettaglio dell''immobile (ovvero di stanze, vani, singole unità immobiliari,ecc.)
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OConfigurazioneTipiOnere.aspx',
'In <b>Altre configurazioni</b> è possibile associare diverse tiplogie di oneri di urbanizzazione (<b>Onere di base</b>) con un tipo di causale oneri. Questo consente all''operatore, alla fine della fase di calcolo, di copiare i risultati di ogni tipologia di onere nell''elenco degli oneri totali della pratica codificandoli secondo una causale onere.
Le causali oneri vengono definite in Archivi > <i>modulo</i> > Tabelle > Causali oneri.
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OTipiOneri.aspx',
'Questa pagina consente di accedere all''elenco delle causali di oneri di urbanizzazione. Oltre alle causali UP (Urbanizzaione primaria) e US (Urbanizzaione secondaria) è possibile creare altre causali in base a quelle eventualmente utilizzate dall''amminstrazione. Ad esempio è possibile creare le causali UP1 (Urbanizzazione primaria di tipo 1), UP2 (Urbanizzazione primaria di tipo 2), UC (Urbanizzazione per superficie di insediamento), qualora queste determinino differenti costi unitari nel calcolo.

Per accedere alla lista delle causali presenti, utilizzare il pulsante <b>Cerca</b>.
Per inserire una nuova causale utilizzare il pulsante <b>Nuovo</b>.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OTipiOneri.aspx',
'La pagina visualizza l''elenco delle causali di urbanizzazione inserite nel sistema e la categoria di oneri di base cui la causale è associata. 
Per accedere alla singola causale, selezionare il relativo codice nella prima colonna della tabella.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OTipiOneri.aspx',
'in questa pagina è possibile inserire o modificare i dati relativi ad una causale di urbanizzazione.

<b>Codice:</b> codice assegnato automaticamente dal sistema.
<b>Onere di base:</b> la categoria di onere di base cui associare la causale (es: una causale "UP1" va associata con l''onere di base "Urbanizzazione primaria").
<b>Descrizione:</b> Sigla per la causale (es: UP1, UC, UT, ecc.).
<b>Descrizione estesa:</b> Descrizione estesa della causale (es: Urbanizzazione primaria 1, Urbanizzaione Costo base, Urbanizzazione totale, ecc.).','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/ODestinazioni.aspx',
'Questa pagina consente di accedere all''elenco delle destinazioni d''uso dell''immobile, utilizzate come parametro per la determinazione dei costi unitari di urbanizzazione. E'' possibile creare diverse destinazioni in base a quelle utilizzate dall''amminstrazione, (ad esempio residenziale, commerciale, turistica, area verde, ecc.). 
Ogni destinazione inserita va associata con una destinazione di base tra quelle presenti nel sistema.

Per accedere alla lista delle destinazioni presenti, utilizzare il pulsante <b>Cerca</b>.
Per inserire una nuova destinazione utilizzare il pulsante <b>Nuovo</b>.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/ODestinazioni.aspx',
'La pagina visualizza l''elenco delle destinazioni inserite nel sistema, assieme alla destinazione di base associata. 
Per accedere alla singola destinazione, selezionare il relativo codice nella prima colonna della tabella.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('DM',
'~/Archivi/Canoni/ConfigurazioneCanoni.aspx',
'La schermata visualizza l''elenco delle differenti configurazioni per il calcolo degli oneri. Ogni configurazione contiene i parametri per il calcolo e i valori degli importi unitari, suddivisi per tipo di zona (A, B, C) e tipo di superficie. 
E'' possibile creare una nuova configurazione in caso di aggiornamegurazione esistentento degli importi unitari, e quindi creare una configurazione per ogni anno. 
Per creare una nuova configurazione utilizzare il pulsante <b>Nuovo</b>.
Per accedere alle impostazioni di una configurazione, selezionarne il nome.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZELISTA.ASP',
'In questa schermata viene riportato l''elenco delle istanze trovate in seguito ad una ricerca nel relativo archivio.
Ogni riga dell''elenco è caratterizzata da una serie di informazioni riassuntive, relative alle singole istanze, che consentono di facilitare l''individuazione dell''istanza che si sta cercando. Tra le altre vengono visualizzate le seguenti informazioni:

<b>Cod</b>: codice dell''istanza; selezionado il codice si accede alla scheda principale dell''istanza
<b>M</b>: selezionando M si accede alla lista dei movimenti dell''istanza
<b>E</b>: selezionando E si accede alla sezione elaborazione istanza
<b>A</b>: indica la presenza di autorizzazioni associate all''istanza
<b>PG</b>: indica il numero di protocollo generale dell''istanza


In alto a sinistra sono inoltre presenti quattro flag che possono essere o meno attiviati per visualizzare rispettivamente:
- Gli eventuali ulteriori indirizzi che si riferiscono all''intervento, di cui alla pratica
- Le istanze che sono state oggetto di sorteggio
- Le istanze che hanno uno o più endoprocedimenti attivati
- Le istanze che hanno uno o più autorizzazioni

In bassso a destra nella schermata, viene riportato il totale delle occorrenze trovate in base ai parametri utilizzati in fase di ricerca; pertanto la ricerca può anche essere utilizzata a fini di conteggio o statistici sulle pratiche.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/ImportazionePeople/ConfigurazioneMappature.aspx',
'Questo pannello permette di effettuare le mappature necessarie per creare una pratica proveniente da People in SIGePro.<br/>
I dati vengono associati tramite delle Tipologie di mappatura che definiscono la posizione dei dati che andranno a popolare le istanze in SIGePro.<br/>
Per ogni tipologia di mappatura è necessario stabilire alcuni dettagli che definiscono quali TAG della domanda XML di People andranno a compilare le informazioni necessarie a SIGePro per portare a termine l''inserimento dell''informazione mappata. </br>
<br/>
L''interfaccia utente mostra 2 griglie collegate tra loro; la prima mostrerà la lista delle mappature inserite mentre la seconda (che verrà valorizzata solo dopo la selezione di una riga della prima griglia) mostrerà le regole associate alla mappatura selezionata.

Vedi allagato <a href="help/Configurazione/Docs/MappaturePeople.pdf">tipologie di mappatura<a>.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/CostoCostruzione/CCConfigurazione.aspx',
'Le superfici che è necessario configurare per il calcolo del contributo sul costo di costruzione sono quelle presenti nel modello del D.M. 10/5/77.
Le superfici possono essere aggiunte in "<b>Archivi</b>" / modulo / "<b>Calcolo oneri</b>" / "<b>Costo di costruzione</b>" / "<b>Tabelle calcolo costo edificio</b>" / "<b><a target="_new" href="Help/Archivi/Img/MenùTipiSuperficie.JPG">Tipi superficie</a></b>".

La <b>causale onere</b> configurata verrà utilizzata per riportare nella gestione oneri il totale calcolato come contributo sul costo di costruzione.

Il <b>Tipo area</b> che rappresenta le zone territoriali omogenee va configurato solo se i coefficienti per il contributo al costo di costruzione dipendono dalle ZTO. Il tipo area che rappresenta ZTO può essere aggiunta in "<b>Archivi</b>" / modulo / "<b>Tabelle</b>" / "<b>Zone Stradario</b>" / "<b>Tipo Zona</b>" Es. Tipo zona ="Zona territoriale omogenea" e quindi aggiungere il dettaglio in  "<b>Archivi</b>" / modulo / "<b>Tabelle</b>" / "<b>Zone Stradario</b>" / "<b>Zonizzazione</b>" Es. "Zona A", "Zona B" facendo attenzione ad associare il dettaglio al tipo zona "Zona Territoriale Omogenea".

Pulsante "<b>Altre configurazioni</b>": vedi l''help della pagina.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/CostoCostruzione/CCConfigurazioneSettori.aspx',
'Il calcolo del contributo sul costo di costruzione può dipendere dal tipo intervento, dalla destinazione, da fattori territoriali come la zona ZTO vedi la scheda "<b>Archivi</b>" / modulo / "<b>Calcolo oneri</b>" / "<b>Costo di costruzione</b>" / "<b>Tabelle coefficienti</b>" / "<b>Listino</b>" alla voce "<b>Coefficienti per tipo intervento</b>". Se il calcolo del coefficiente per individuare il contributo dipende anche da altri fattori allora è possibile indicare una tabella in "<b>Archivi</b>" / modulo / "<b>Tabelle</b>" / "<b>Tipi informazioni</b>", specificarne i dettagli in "<b>Archivi</b>" / modulo / "<b>Tabelle</b>" / "<b>Dettagli informazione</b>" ed aggiungerla alla configurazione tramite questa voce. Per completare la configurazione vanno specificate le condizioni che permettono di utilizzare le voci della tabella in "<b>Archivi</b>" / modulo / "<b>Calcolo oneri</b>" / "<b>Costo di costruzione</b>" / "<b>Tabelle coefficienti</b>" / "<b>Altre tabelle</b>" e specificarne i coefficienti in "<b>Archivi</b>" / modulo / "<b>Calcolo oneri</b>" / "<b>Costo di costruzione</b>" / "<b>Tabelle coefficienti</b>" / "<b>Listino</b>" alla voce "<b>Coefficienti altre tabelle</b>". 

In questa sezione vanno indicati gli ulteriori parametri che rientrano nella definizione del costo convenzionale dell''edificio. Tali parametri vanno preliminarmente definti all''interno di <b>tipo</b> e <b>dettaglio informazione</b>. In questa sede vengono invece definiti quali altri parametri, tra le categorie identificate in <b>tipo</b> e <b>dettaglio informazione</b>, potranno essere utilizzati nell''ambito di uno specifico listino coeffiioenti.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/CostoCostruzione/CCDestinazioni.aspx',
'In questa sezione è possibile gestire le destinazioni che saranno poi utilizzate per il calcolo del contributo sul costo di costruzione, ogni destinazione deve appartenere a delle destinazioni di base che sono utilizzate da SIGePro per capire di che tipo di destinazione si tratta.
Es. se il comune ha dei coefficienti diversi in base alle seguenti destinazioni: "<b>Commerciali</b>", "<b>Commerciali centro storico</b>", "<b>Direzionali</b>" bisognerà aggiungere le 3 destinazioni menzionate sopra indicando che ognuna appartiene alla destinazione di base "Turistica, commerciale, direzionale o sportiva".
E'' comunque necessario aggiungere tutte le destinazioni che devono prendere parte al calcolo del contributo.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/CostoCostruzione/CCDetermTipoCalcolo.aspx',
'Questa sezione deve essere configurata per definire in base al tipo di intervento e alla destinazione che tipo di calcolo deve essere utilizzato.
In genere per una destinazione "<b>Residenziale</b>" il tipo di calcolo viene fatto utilizzando il <b>modello1</b> D.M. 10/5/77 per le "<b>"Nuove costruzioni</b>" e per le "<b>"Ristrutturazioni</b>", mentre si utilizzerà il tipo di calcolo "<b>Modello1 per il progetto + Modello2 per lo stato attuale</b>" per gli "<b>Apliamenti</b>".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/ODestinazioni.aspx',
'In questa pagina è possibile inserire o modificare i dati relativi ad una destinazione d''uso per l''immmobile.

<b>Codice:</b> codice assegnato automaticamente dal sistema.
<b>Destinazione di base:</b> la destinazione di base cui associare la destinazione (es: una destinazione "Commerciale" può venire associata con la destinazione di base "Costruzioni civili").
<b>Destinazione:</b> Descrizione estesa della destinazione; la descrizione potrebbe anche contenere più destinazioni per le quali nel cacolo valgono gli stessi costi unitari (es: Residenziale, alberghi o pensioni)
<b>Unità di misura:</b> Definisce se il calcolo per questa destinazione va effettuato in base ai metri quadrati o in base ai metri cubi.
<b>Ordinamento:</b> Definisce in quale posizione la singola destinazione deve apparire nella combo box.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OInterventi.aspx',
'Questa pagina consente di accedere all''elenco degli interventi. E'' possibile creare diversi interventi in base a quelli utilizzati come parametri nel calcolo degli oneri dall''amministrazione. Esempi di interventi sono: "Nuova costruzione", "Nuovi insediamenti PIP", "demolizione e ricostruzione", ecc..

Per accedere alla lista delle causali presenti, utilizzare il pulsante <b>Cerca</b>.
Per inserire una nuova causale utilizzare il pulsante <b>Nuovo</b>.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_CONCESSIONIUSO.ASP',
'La tabella concessioni uso è legata ai giorni in cui si svolge un mercato ed indica l''utilizzo del posteggio nell''arco della giornata. In genere viene compilata con diciture come ad esempio "Giornata intera", "Mattina", "Pomeriggio". Viene utilizzato per discriminare un posteggio nei diversi momenti della giornata.

Nelle fiere può essere utilizzato per discriminare i giorni della fiera, ad esempio in una fiera che si svolge tutte le domeniche del mese di maggio questa tabella può contenere "prima domenica", "seconda domenica", ...
In questo caso ad ogni domenica è possibile associare un "peso" che è l''importanza della domenica per una eventuale graduatoria.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OInterventi.aspx',
'In questa pagina è possibile inserire o modificare i dati relativi ad un intervento, utilizzato come parametro per la definizione ed il calcolo degli oneri di urbanizzazione.

<b>Codice:</b> codice assegnato automaticamente dal sistema.
<b>Intervento di base:</b> la categoria di intervento di base predefinito cui associare l''intervento (es: un intervento "Impianti industriali - Nuovi insediamenti PIP" può venire associato con l''intervento di base "Nuove costruzioni").
<b>Intervento:</b> Descrizione estesa dell''intervento (es: "Impianti industriali - Ampliamento", ecc.).
<b>Ordinamento:</b> Definisce in quale posizione la singolo intervento deve apparire nella combo box.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OIndiciTerritoriali.aspx',
'La pagina visualizza l''elenco delle differenti combinazioni di indici territoriali che possono essere utilizzati nella determinazione degli oneri. 
Per accedere al singolo indice, selezionare il relativo codice nella prima colonna della tabella.
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OIndiciTerritoriali.aspx',
'In questa pagina è possibile inserire o modificare i dati relativi agli indici territoriali, utilizzati come parametro per la definizione ed il calcolo degli oneri di urbanizzazione. 
Ogni elemento può essere composto dalla combinazione di uno o più indici, in base alle differenti combinazioni utilizzate nel calcolo dall''amministrazione; A seconda dei casi potrano essere inseriti uno, due o tre indici.

<b>Codice:</b> codice assegnato automaticamente dal sistema.
<b>Densità di Zona</b> DTZ.
<b>Indice di fabbricabilità territoriale</b> IFT.
<b>Indice di fabbricabilità fondiaria</b> IFF.
<b>Descrizione:</b> la descrizione viene utilizzata come valore nelle combo box all''interno del calcolo oneri per rappresentare il singolo indice o combinazione di indici utilizzati nel calcolo. Pertanto in questo  campo è possibile inserire anche categorie descrittive (ad es: "< 1,3" o "compreso tra 1,5 e 3").
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OValiditaCoefficienti.aspx',
'Questa pagina consente di accedere all''elenco dei listini, ovvero delle differenti tabelle che riportano tutti i coefficienti (detti anche costo unitario) utilizzati nel calcolo, o di creare un nuovo listino. 
Un nuovo listino può essere creato a seguito di aggiornamento dei coefficienti su base ISTAT, aggiornamento che determina la ridefinizione dei coefficienti di calcolo per l''amministrazione. La presenza di differenti listini consente di aggiornare i coefficienti nel corso degli anni. Ad esempio un listino può avere validità per gli anni 2000 - 2005, un altro per gli anni dal 2005 ad oggi, ecc.

Per accedere all''elenco dei listini presenti, utilizzare il pulsante <b>Cerca</b>.
Per inserire un nuovo listino utilizzare il pulsante <b>Nuovo</b>.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OValiditaCoefficienti.aspx',
'La pagina consente di visualizzare o inserire le infomazioni di dettaglio del singolo listino, ovvero della tabella contenente i coefficienti (costo unitario) per il calcolo degli oneri. I campi utilizzati sono:

<b>Codice:</b> codice assegnato automaticamente dal sistema.
<b>Descrizione:</b> descrizione estesa del listino
<b>Data inizio validità:</b> la data dalla quale il listino è valido. In presenza di più listini, nella fase di calcolo degli oneri il sistema va a proporre il listino corrispondente alla data in cui viene eseguito il calcolo degli oneri. La data di validità di un listino va dalla data inserita nel campo fino alla data di validità specificata per il listino imediatamente più recente.

Una volta creato un nuovo listino, tramite i due pulsanti posti in fondo alla pagina, è possibile accedere all''area di inserimento dei coefficienti del listino:

<b>Tabella D:</b> viene utilizzato per imputare i coefficienti in caso di costruzioni ed impianti industriali, qualora questi dipendano solo dalle classi di addetti all''impianto.
<b>Tabelle ABC:</b> viene utilizzato per imputare i coefficienti in caso di costruzioni civili ed industriali qualora questi dipendano da più parametri (ad es: Intervento, Zona del PRG ed Indice di Fabbricabilità Fondiaria, ecc.).
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OValiditaCoefficienti.aspx',
'La pagina visualizza l''elenco dei listini presenti nel sistema,ognuni dei quali contiene tutti i coefficienti definiti dall''amministrazione per il calcolo degli oneri di urbanizzazione. 
Per accedere al singolo listino, selezionare il relativo codice nella prima colonna della tabella.
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZEFIDEJUSSIONILISTA.ASP',
'In questa schermata viene visualizzata la lista delle fideiussioni presentate per la pratica.
Per accedere al dettaglio di una singola fideiussione, selezionare il codice sotto la prima colonna.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CE',
'~/Archivi/CalcoloOneri/Urbanizzazione/OInterventi.aspx',
'La pagina visualizza elenco degli interventi inseriti nel sistema e la categoria di interventi di base cui la causale è associata. 
Per accedere al singolo intervento, selezionare il relativo codice nella prima colonna della tabella.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZEPROCEDIMENTI.ASP',
'La schermata riporta l''elenco degli endoprocedimenti che è possibile attivare nell''ambito del procedimento.
In base alla configurazione del singolo modulo software, l''attivazione di un endoprocedimento può comportare la creazione di ulteriori attività da gestire nell''ambito dle procedimento, tipicamente attività di trasmissione di documenti agli enti interessati per conoscenza, per verifiche, per ottenere un parere o nulla osta, ecc.

Per attivare un endoprocedimento, e quindi generare una serie di attività nella gestione della pratica:
- spuntare il campo <b>Autoriz.</b> (Autorizzativo), nel caso in cui sia necessario inviare comunicazioni, documentazione, richieste, ecc. all''ente interessato.
- spuntare il campo <b>Acquis.</b> (Acquisito) nel caso in cui il nulla osta o autorizzazione sia stato acquisito dal richiedente precedentemente alla presentazione dell''istanza allo Sportello. In questo caso il sistema non produce attività aggiuntive di gestione ma registra unicamente la data e i dettagli del parere.

Con la spunta, il sistema inserisce la data attuale (modificabile) che viene utilizzata anche quale data di scadenza per l''eventuale movimento generato dall''attivazione dell''endoprocedimento. Il sistema spunta automaticamente anche il campo <b>Attivato</b>.
E'' possibile attivare/disattivare endoprocedimenti anche in un secondo momento. Per salvare le modifiche è necessario utilizzare il pulsante <b>Ok</b>, posto in fondo alla pagina.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZEALLEGATI.ASP',
'La pagina visualizza il dettaglio della documentazione relativa ad ogni endoprocedimento attivato.

Nel caso in cui l''endoprocedimento determini attività di richiesta o comunicazione all''ente competente (endoprocedimento <b>Autorizzativo</b> ), vengono visualizzati i documenti relativi che è necessario presentare allo Sportello e che verranno inviati all''ente per l''evasione della richiesta/parere di cui all''endoprocedimento. In questo caso è possibile spuntare uno o più dei seguenti campi:
- PRESENTE se il documento è stato presentato con la domanda, 
- VERIFICATO se il documento presentato è effettivamente quello richiesto
- VALIDO se il documento è valido, ovvero contiene le informazioni richieste 
Per ogni documento previsto è possibile inserire il relativo file presentato dal richiedente, selezionando il codice del documento presente nella prima colonna e specificando nella finestra seguente il nome ed il file da caricare nel sistema.

Nel caso in cui l''endoprocedimento sia invece <b>Acquisito</b>, vengono presentati alcuni campi che consentono di inserire gli estremi dell''autorizzazione / nulla osta fornita dal richiedente come documentazione per la pratica.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/Urbanizzazione/OTabellaABC.aspx',
'In questa pagina vengono imputati o visualizzati i coefficenti per il calcolo degli oneri di urbanizzazione, in base ai differenti parametri coinvolti nel calcolo e precedentemente definiti. 
Si ricorda che l''inserimento dei valori dei coefficienti, prevede la preliminare definizione dei parametri che influenzano il calcolo (Zone territoriali, Destinazioni, Interventi, Indici, Causali oneri d Urbanizzazione, ecc.).

Selezionando differenti combinazioni dei parametri che sono stati definiti precedentemente e che rientrano nel calcolo, il sistema propone differenti interfacce di input, che consentono di inserire i singoli coefficienti e di registrarli nel sistema. Ad ogni combinazione di parametri, nella parte sottostante della pagina vengono visualizzati una serie di campi che consentono l''inserimento dei valori dei coefficienti.

Nel caso in cui una combinazione di parametri non determini un coefficiente specifico, lasciare il campo vuoto.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZESELEZIONE.ASP',
'Tramite questa pagina è possibile inserire una nuova pratica nel sistema o cercare all''interno del relativo archivio, contenente tutte le pratiche già inserite (in corso, chiuse, archiviate, ecc.).

Per rintracciare una o più pratiche presenti all''interno dell''archivio, utilizzare i campi presenti nella pagina per specificare eventuali filtri di ricerca e selezionare successivamente il pulsante <B>Cerca</B> posto in fondo alla pagina.
Per inserire una nuova pratica selezionare il pulsante <B>Nuovo</B> posto in fondo alla pagina, che consente di accedere alla schermata per l''inserimento dei dati della pratica.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/CalcoloOneri/CostoCostruzione/CCTabella3.aspx',
'N.B.: Il campo <i>''Dettaglio superficie''</i> non va quasi mai compilato perchè, così come dettato dalla normativa (L. 28 gennaio 1977, n.10), il rapporto percentuale, che determina l''intervallo di variabilità e conseguente incremento, è calcolato sul totale della superficie netta di servizi e accessori relativi alla parte residenziale. <br/>
Solo in rari casi, vedi <a href="Help/Archivi/Img/OneriPG.JPG" title="Modello per la Determinazione del Contributo di Concessione">Oneri del Comune di Perugia</a>, occorre inserire anche il dettaglio superficie e nello specifico solo quando l''incremento per servizi ed accessori è combinazione di incrementi parziali determinati sulla base di rapporti percentuali che coinvolgono le singole superfici per servizi.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_CONFERENZAINVITATI.ASP',
'La pagina consente di inserire i dati relativi ad una singola voce di costo per la pratica. Tra le differenti informazioni che si possono inserire si puntualizzano le seguenti:

<b>Data Registrazione:</b> è la data in cui si genera l''onere o in cui viene inserito nel sistema.
<b>Tipo Movimento che determina la scadenza:</b> può essere impostato un movimento che determina, una volta eseguito, la data di scadenza dell''onere.
<b>Importo per causale:</b> è l''importo in euro dell''onere.
<b>Riferimento documento di pagamento:</b> il campo è visibile solo se è valorizzata la data di pagamento e consente di inserire i riferimenti del bonifico, assegno, ecc.

Il pulsante <b>Rateizzazione</b>, visibile solo dopo l''inserimento dell''onere, consente di accedere alla funzione per la rateizzazione del singolo importo.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/Urbanizzazione/OIDettaglio.aspx',
'Questa pagina consente l''inserimento di diverse tipologie di informazioni a seconda che la modalità di imputazione delle superfici o dei volumi fiscali sia <B>di dettaglio</B> o <b>generica</b>. Tale parametro è definito nella configurazione degli oneri di urbanizzazione.

<b><u>Modalità di imputazione di dettaglio</u></b>
La schermata consente di specificare la destinazione d''uso e la descrizione del corpo da cubare. L''imputazione delle misure dei singoli elementi, che determinano poi la superficie o il volume del corpo da cubare, viene fatta nel dettaglio delle superfici in seguito al salvataggio dei dati descrittivi.
Le informazioni presentate sono le seguenti:
<b>Tipologia superficie:</b> rappresenta una categoria di destinazione d''uso del fabbricato.
<b>Dettaglio superficie:</b> rappresenta la destinazione d''uso del fabbricato.
<b>Descrizione:</b> descrizione del corpo da cubare (es: piano1, piano terra, unità immobiliare 1A, garage, ecc.)

<b><u>Modalità di imputazione generica</u></b>
In questo caso la schermata consente di specificare la destinazione d''uso, la descrizione del corpo da cubare e il totale della superficie o del volume fiscale del corpo da cubare. Oltre a <b>Tipologia superficie, Dettaglio superficie e Descrizione</b>, viene presentato il campo <b>Valore</b>, nel quale è necessario specificare il totale dei metri cubi o quadrati per quel corpo.

','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/Urbanizzazione/OIDettaglio.aspx',
'In questa sezione è ncessario specificare le superfici o volumi fiscali dei differenti corpi oggetto di cubatura che costituiscono l''immobile. Un <B>corpo da cubare</b> è una parte dell''immobile (ad esempi un piano, una porzione, un vano, ecc.) caratterizzato da specifici coefficienti. Le superifici o volumi inseriti verranno utilizzate per il calcolo degli oneri di urbanizzazione sulla base del listino coefficienti precedentemente selezionato.
Per inserire una nuova superfice che rientra nel calcolo degli oneri utilizzare il pulsante <b>Nuovo</b>.

Le superfici dei vari corpi da cubare vengono visualizzate nella pagina in una lista all''interno della sezione <b>Superfici utili</b>.
In base alla configurazione selezionata, viene visualizzata o meno, nella parte sottostante della pagina, la sezione <b>Dettaglio superfici</b>, contenente una ulteriore lista con il dettaglio delle varie superfici utili che costituiscono un singolo corpo da cubare. E'' possibile utilizzare infatti due modalità di imputazione delle superfici utili:

1 - Una <b><u>modalità di dettaglio</u></b> in cui vengono definite le dimensioni in metri di ogni corpo o delle singole parti di esso: il sistema provvede a calcolare le singole superfici / volumi fiscali; con questa configurazione è possibile suddividere un corpo da cubare in ulteriori elementi (ad esempio le singole stanze di un piano o le singole unità imobiliari di un piano di un palazzo) ognuno caratterizzato da una cubatura. Utilizzando il pulsante <img src="help/Istanze/Img/OneriDetSupButt.gif" border="0">, nella sezione <b>Dettaglio superfici</b> vengono visualizzati i singoli elementi appartenenti ad ogni corpo da cubare.
In questo caso per inserire le singole superfici di dettaglio relative ad un corpo, utilizzare il pulsante <b>Nuovo</b> posto sotto la sezione <b>Dettaglio superfici</b>. Utilizzare il pulsante <img src="help/Istanze/Img/OneriEditSupButt.gif" border="0"> per modificare i dati delle superfici di dettaglio già inserite.

2 - Una <b><u>modalità generica</u></b> in cui si definisce la superficie o il volume totale del singolo corpo da cubare senza definire il dettaglio. In questo caso per inserire il valore della superficie o volume fiscale del corpo, utilizzare il pulsante <img src="help/Istanze/Img/OneriEditSupButt.gif" border="0">.

Per far si che le modifiche o gli inserimenti effettuati vadano ad aggiornare il calcolo totale è necessario selezionare il pulsante <b>Procedi</b>. Selezionando il pulsante <b>Chiudi</b> le modifiche o gli inserimenti effettuati non vanno ad aggiornare il calcolo totale per l''immobile. 


<u>Nel caso di un nuovo inserimento, in seguito alla fase di definizione delle superfici o dei volumi è necessario definire i valori degli altri coefficienti  che intervengono nel calcolo, dalla pagina <b>Calcolo degli oneri di Urbanizzazione<b></u>','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/Urbanizzazione/OICalcoloTot.aspx',
'Per ogni pratica è possibile registrare e salvare diversi calcoli degli oneri di urbanizzazione che vengono visualizzati nella lista presentata nella pagina.

Per accedere alla procedura che consente di eseguire e registrare un nuovo calcolo, selezionare il pulsante <b>Nuovo</b>. Ogni calcolo salvato viene visualizzato nella lista. 
Per eliminare un calcolo utilizzare il pulsante <b>X</b>, posto a lato di ogni calcolo salvato.
Per accedere ai dettagli di un calcolo salvato, selezionare il codice nella prima colonna della lista.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/Urbanizzazione/OICalcoloTot.aspx',
'La pagina presenta i dati di riepilogo relativi ad un singolo calcolo. 

Il calcolo degli oneri richiede l''esecuzione dei seguenti passaggi: 
a - <b><u>definizione dei dati generali</u></b>
b - <b><u>definizione delle superfici o dei volumi</u></b>
c - <b><u>definizione dei coefficienti relativi ai parametri utilizzati</u></b>.

In questa pagina vanno definiti prima di tutto i dati generali:
<b>Data: </b> la data in cui viene eseguito il calcolo o in cui è stato impuatato l''onere.
<b>Listino coefficienti:</b> da utilizzare per il calcolo, tra quelli proposti  dal sistema. In base alla data del calcolo, il sistema propone automaticamente il listino corrispondente in vigore.
<b>Descrizione: </b>la descrizione testuale del calcolo.

Per registrare le informazioni inserite utilizzare il pulsante <b>Salva</b>.
Selezionare il pulsante <b>Dettaglio</b> per accedere all''area per la registrazione delle superfici o dei volumi fiscali dell''immobile.

- Nel caso in cui siano già state registrate superfici o volumi fiscali per l''immobile, la pagina visualizza una tabella riportante le differenti destinazioni d''uso dei volumi. 
- Nel caso in cui siano state definite le superfici o i volumi fiscali e la tabella non riporti il valore degli oneri, è necessario utilizzare il pulsante <img src="help/Istanze/Img/OneriEditSupButt.gif" border="0"> per definire i valori dei coefficienti utilizzati per il calcolo.
- Nel caso in cui siano state definite sia le superfici che i valori dei coefficienti e la tabella riporti il valore degli oneri, è possibile utilizzare il pulsante <img src="help/Istanze/Img/OneriEditSupButt.gif" border="0"> per accedere al dettaglio del calcolo e dei coefficienti utilizzati, per ogni destinazione d''uso.

Alla fine della fase di calcolo degli oneri, è possibile riportare gli importi visualizzati, nella pagina di rendicontazione generale degli oneri della pratica (<a target="_new" href="Help/Istanze/Img/OneriSchGen.JPG">Vedi</a>) tramite il pulsante <b>Copia Oneri</b>.
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('DM',
'~/Archivi/Canoni/ConfigurazioneCanoni.aspx',
'La schermata di una singola configurazione del calcolo del canone demaniale marittimo consente di definire i parametri di calcolo, nonchè gli importi unitari per metro quadrato e per anno.
A seguito si riportano le principali informazioni che è possibile inserire per una singola configurazione:

<b>Valore base OMI</b>: valore base ottenuto come media dei valori OMI per l''anno; viene utilizzato per il calcolo del canone relativo alle pertinenze.
<b>Coefficiente OMI</b>: coefficiente che interviene nel calcolo del canone relativo alle pertinenze in base alla Legge 296/2006, stabilito pari a 6,5 a livello nazionale.
<b>Causale onere</b>: rappresenta la dicitura con la quale l''importo totale del canone viene riportato nella gestione oneri; tale voce va precedentmente inserita tra le causali oneri.
<b>Canone minimo</b>: importo minimo del canone.

E'' possibile inoltre specificare eventuali addizionali (Comunale e Regionale) al canone totale, che possono rientrare nella determinazione del totale da corrispondere. Per ognuna delle addizionali può essere specificato: 
<b>Percentuale</b>: % del canone totale da destinare all''amministrazione.
<b>Causale onere addizionale</b>:  rappresenta la dicitura con la quale l''importo totale del canone viene riportato nella gestione oneri.


<b><u>Importi unitari superfici</u></b>
In questa sezione vanno inseriti gli importi unitari per tipo di superficie e per categoria, relativi all''anno di riferimento. Se non vengono utilizzate le categorie nel calcolo dei canoni, e quindi valori unitari non variano con le categorie, viene presentata una sola colonna nella quale inserire i valori unitari.
I valori unitari sono definiti in euro al metro quadrato per anno.

<b><u>Riduzioni classi OMI</u></b>
In questa sezione vanno definite le percentuali di riduzione per le differenti classi di superficie previste dal metodo di calcolo OMI per le pertinenze. Tali riduzioni sono definite dalla Legge 296/2006. Nel caso in cui una classe non comporti riduzione, inserire nel relativo campo il valore 0.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('DM',
'~/Istanze/CalcoloCanoni/IstanzeCalcoloCanoni.aspx',
'In questa schermata è possibile eseguire il calcolo degli importi dovuti relativi al canone demaniale, relativo ad una concessione. Il calcolo utilizza le impostazioni relative ad un determinato anno e consente di specificare le singole tipologie di superfici coinvolte nella concessione. 
La schermata si compone di una sezione contenente i dati generali relativi al calcolo,  e di una sezione sottostante nella quale vanno specificate le caratteristiche delle differenti tipologie di superficie coinvolte nel calcolo.

Vengono a seguito descritte le principali informazioni richieste:
<b>Configurazione utilizzata</b>: va specificato l''anno relativamente al quale utilizzare i parametri di calcolo.
<b>Descrizione</b>: descrizione che identifica il singolo calcolo.
<b>Percentuale addizionale regionale</b>
<b>Percentuale addizionale </b>

Una volta inserite le informazioni generali del calcolo è necessario selezionare il pulsante <b>Salva</b> per accedere alla sezione di inserimento delle superfici.
Inserire le informazioni relative alle diverse superifici specificando nell''ordine:
1. Categoria 
2. Superficie
3. Metri quadrati relativi alla tipologia di superficie selezionata
4. L''importo al metro quadrato viene riportato automaticamente
5. Eventualmente modificare il periodo, inserendo il numero di giorni di effettivo utilizzo della superficie selezionata. 
Al termine dell''inserimento di una singola superficie è necessario salvare i dati tramite il pulsante di salvataggio posto sulla destra. E'' inoltre possibile eliminare dal calcolo una superficie inserita, tramite il pulsante elimina, posto sulla destra.
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MOVIMENTIPRATICHE.ASP',
'La pagina visualizza il dettaglio di un singolo movimento; un movimento rappresenta una fase di gestione dell''istanza che, una volta completata, viene registrata a carico dell''istanza stessa; in una istanza possono essere presenti diversi tipi di movimento. 
Alcuni dati relativi al movimento vengono precompilati in base alle regole che definiscono le caratteristiche dello specifico iter applicato al procedimento. 
I principali dati che è opportuno compilare per un movimento sono:<BR>
<B>Data:</B> la data di completamento dell''attività rappresentata dal movimento (es: la data di invio di una comunicazione, la data di completamento di una fase di controllo, ecc. ).
<B>Nr protocollo:</B> il protocollo viene utilizzato qualora il movimento rappresnti una fase di ricezione o di invio di documenti, pareri, atti, comunicazioni, ecc. Negli altri casi (ad esempio per un movimento "istruttoria") tale dato non deve essere inserito.
<B>Data protocollo:</B> data del protocollo in uscita o in entrata, qualora sia stato inserito un numero di protocollo relativo al movimento.
<B>Esito positivo:</B> questo dato è presente solo in alcuni tipi di movimento e rappresenta l''esito della fase rappresentata dal movimento. I valori SI e NO discriminano le successive fasi della pratica.
<B>Parere:</B> in questo campo vanno inseriti in maniera estesa eventuali pareri o prescrizioni associati con il movimento, qualora pretinenti.
<B>Note:</B> campo che può essere utilizzato per ventuali annotazioni relative alla fase.

I tasti <B>P</B> consentono di pubblicare o meno tutti i dati del movimento, oppure di pubblicare solamente i dati contenuti nel campo "parere".','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZE.ASP',
'La scheda principale dell''istanza consente di:
- inserire tutte le informazioni necessarie per registrare una nuova pratica nel sistema. 
- visualizzare le informazioni relative a pratiche già inserite nel sistema. 

Nel caso in cui si stia registrando una nuova istanza è necessario inserire le informazioni minime evidenziate con l''asterisco. Una volta inserite le informazioni negli appositi campi va selezionato il pulsante <b>SALVA</b> in fondo alla pagina per salvare i dati o le modifiche effettuate.

Nel caso di modifica dei dati di una istanza esistente, è necessario selezionare il pulsante <b>SALVA</b> in fondo alla pagina per salvare le modifiche effettuate. 

<B><u>Funzioni accessibili dalla scheda principale dell''istanza</u></B>
Una volta che la pratica sia stata inserita nel sistema, vengono presentati ulteriori link o pulsanti che consentono di accedere ad ulteriori funzioni. 

<B>Pulsanti posti in fondo alla pagina:</B>
<B>Altri dati</B>: consente di accedere a diverse schede per l''inserimento di dati aggiuntivi in modo da poter registrare ulteriori informazioni che non sono previste nella scheda principale dell''istanza.
<B>Altri indirizzi</B>: consente di accedere ad una sezione in cui è possibile registrare eventuali indirizzi ulteriori relativi all''intervento.
<B>Soggetti collegati</B>: consente di accedere alla sezione per la registrazione di ulteriori soggetti formalmente coinvolti nel procedimento (es: comproprietari, soci, direttori dei lavori, ecc.).
<B>Gestione endo</B>: consente l''accesso alla sezione che riepiloga gli endoprocedimenti attivati per la pratica.
<B>Elaborazione istanza</B>: consente l''accesso ad un pannello di controllo per la gestione delle varie attività legate alla gestione del procedimento.
<B>Gestione oneri</B>: permette l''accesso alla sezione per la rendicontazione della componente finanziaria relativa alla pratica.
<B>Stampe</B>: accesso alle funzioni di stampa di documenti a partire dai dati dell''istanza.
<B>Documenti</B>: accesso alla lista di tutti i documenti ed i files allegati alla pratica.
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('DM',
'CL_ISTANZEONERILISTA.ASP',
'In questa sezione viene presentata una rendicontazione di tutte le voci di costo (entrate o uscite) relative alla pratica. Per accedere al dettaglio di una singolo voce di costo è necessario selezionare la causale nell''elenco.

E'' possibile inserire una nuova voce di costo (in entrata o uscita) utilizzando il pulsante <b>Nuovo</b> in fondo alla pagina.
Il pulsante <b>Stampa</b> produce un documento riassuntivo con la situazione degli oneri per la pratica.
Il pulsante <b>Modifica</b> consente di accedere ad un pannello per la modifica dei differenti dati relativi alle voci di costo.<BR>
Qualora vengano configurati i relativi parametri in configurazione del sistema, la pagina visualizza altri pulsanti:
<b>Fidejussioni:</b> consente di registrare i dati relativi ad eventuali fideiussioni presentate a garanzia del pagamento, quando questo sia rateizzato.
<b>Calcolo del canone:</b> consente di accedere alla sezione per la determinazione del Contributo Demaniale Marittimo.
','2');
