CONTENTTYPE,
HELPTEXT,
TAB) values ('CE',
'CL_ISTANZEONERILISTA.ASP',
'In questa sezione viene presentata una rendicontazione di tutte le voci di costo (entrate o uscite) relative alla pratica. Per accedere al dettaglio di una singolo voce di costo è necessario selezionare la causale nell''elenco.

