Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/CCICalcoliTot.aspx',
'La schermata visualizza l''elenco dei diversi calcoli relativi al contributo sul costo di costruzione, relativi alla pratica. Per accedere al dettaglio di un singolo calcolo, selezionarne il codice nella prima colonna.
Per eliminare un calcolo dall''istanza, selezionare l''icona "X" posta sulla, destra a fianco del calcolo.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/CCICalcoliDettaglio.aspx',
'In questa schermata vanno specificate le unità immobiliari (alloggi) che costituiscono l''edificio, suddivise in base alle differenti classi di superficie previste per il calcolo ed in base alla destinazione d''uso delle superfici stesse.
Per inserire gli alloggi appartenenti ad una classe di superficie utilizzare il pulsante <B>Nuovo</B>.
Utilizzare il pulsante <img src="help/Istanze/Img/OneriEditSupButt.gif" border="0"> per accedere al dettaglio di una classe di alloggi ed eventualmente modificare i dati.
Una volta terminata l''operazione di inserimento di tutti gli alloggi, utilizzare il pulsante <B>Procedi</B> per passare alla successsiva fase di calcolo.
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/CCICalcoliDettaglio.aspx',
'La schermata consente di specificare la destinazione d''uso, la descrizione e la dimensione delle singole superfici inserite.
<b>Tipologia superficie:</b> rappresenta una categoria di destinazione d''uso della superficie.
<b>Dettaglio superficie:</b> rappresenta un ulteriore dettaglio relativo alla destinazione d''uso, che può incidere nelle caratteristiche utili per la determinazione del Costo Totale di Costruzione.
<b>Descrizione:</b> descrizione del tipo di alloggio/i (es: piano1, piano terra, unità immobiliare 1A, garage, negozio, deposito negozio, ecc.).
<b>Numero alloggi:</b> numero delle unità imobiliari dotate delle stesse caratteristiche.
<b>Su:</b>  superficie di ogni unità imobiliare dotata delle stesse caratteristiche (es: per 4 appartamenti residenziali, ognuno di 120 mq, inserire Numero alloggi = 4, Su = 120 )

Salvare i dati inseriti tramite il pulsante <b>Salva</b>.
Per eliminare i dati inseriti, utilizzare il pulsante <b>Elimina</b>.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/CCITabella4.aspx',
'La schermata consente di specificare le eventuali caratteristiche che determinano un incremento del Costo Totale di costruzione; per selezionare una o più caratteristiche spuntare la casella a fianco.
Al termine dell''operazione selezionare il pulsante <B>Procedi</B>, per passare alla schermata di riepilogo del calcolo, contenente tra l''altro l''importo del Costo Totale di costruzione.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/DeterminazioneCCRiepilogo.aspx',
'La schermata presenta il riepilogo delle caratteristiche dell''edificio che determinano il Costo Totale di costruzione, al quale verrà successivamente applicata una percentuale per determinare il Contributo sul Costo di Costruzione.
Per tornare alla schermata principale del calcolo, selezionare il pulsante <b>Chiudi</b>.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/CalcoloOneri/CostoCostruzione/CCICalcoliTot.aspx',
'La pagina presenta i dati di riepilogo relativi ad un singolo calcolo del Contributo sul Costo di Costruzione e consente di registrare i dati relativi ad un calcolo.
Il calcolo del contributo richiede l''esecuzione dei seguenti passaggi: 
a - <b><u>definizione dei dati generali</u></b>
b - <b><u>definizione del costo totale di costruzione sulla base delle caratteristiche dell''edificio</u></b>
c - <b><u>definizione della percentiuale del costo totale di costruzione </u></b>
Il sistema provvede successivamente a calcolare l''importo dovuto quale Contributo sul Costo di Costruzione

Per inserire un nuovo calcolo è prima di tutto necessario registrarne i dati principali che sono: <BR>
<B>Data:</B> data del calcolo
<B>Listino coefficienti:</B> quali coefficienti si intende utilizzare per il calcolo; generalmente ogni anno i coefficienti vengono aggiornati in un nuovo listino. 
<B>Tipo intervento:</B> l''intervento che si intende eseguire sull''edificio.
<B>Destinazione:</B> Residenziale o turistico -  commerciale.
<B>Tipo calcolo:</B> Perizia, calcolo su modello 1, confronto tra stato di aftto e di progetto, ecc.
<B>Descrizione:</B> descrizionne del calcolo (es: "calcolo oneri - anno 2005").

Per registrare le informazioni inserite utilizzare il pulsante <b>Salva</b>.
Selezionare il pulsante <img src="help/Istanze/Img/OneriDetSupButt.gif" border="0">, posto sotto la colonna "Costo di costruzione", per accedere all''area per la registrazione delle caratteristiche dell''immobile ed il cacolo del costo totale di costruzione. 
Il pulsante <img src="help/Istanze/Img/OneriDetSupButt.gif" border="0">, posto sotto la colonna "Percentuale contributo", consente invece di impostare la percentuale per la determinazione del contributo.

Nel caso in cui il tipo di calcolo sia una perizia del Tecnico professionista, l''importo del Costo di Costruzione non andrà calcolato, ma inserito a mano nel relativo campo.
Nel caso in cui l''importo del Costo di Costruzione sia dato dalla differenza tra gli importi relativi allo stato di progetto e allo stato attuale (es: in caso di ampliamenti), andranno eseguiti due calcoli: la differenza degli importi ottenuti costituisce il Costo Totale sul quale calcolare il contributo.

Alla fine della fase di calcolo, il sistema visualizza l''ammontare del contributo sul Costo di Costruzione; a questo punto è necessario salvare tutti i dettagli del calcolo tramite il pulsante <b>Salva contributo</b>. E'' inoltre possibile riportare l''importo finale nella pagina di rendicontazione generale degli oneri della pratica (<a target="_new" href="Help/Istanze/Img/OneriSchGen.JPG">Vedi</a>), tramite il pulsante <b>Copia Oneri</b>.
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ELABORAZIONE.ASP',
'Elaborazione istanza consiste in un pannello per il controllo e la gestione delle fasi (o movimenti) del procedimento amministrativo. All''interno di quest''area è possibile verificare lo stato di avanzamento del procedimento di cui all''istanza, oppure aggiornare, tramite l''inserimento di informazioni, lo stato del procedimento.

I movimenti presentati possono essere <B>già eseguiti</B> (evidenziati in colore verde), o <B>da eseguire</B> (evidenziati in colore blu); in particolare questi ultimi vengono proposti sulla base di un modello  che prevede una successione di diverse fasi per addivenire alla conclusione del procedimento amministrativo.
Per ogni movimento vengono evidenziate le seguenti informazioni in forma tabellare:
<B>Presentazione:</B> la data effettiva di esecuzione o di registrazione del movimento.
<B>Scadenza:</B> la data di scadenza prevista sulla base del modello di procedimento.
<B>Amministrazione:</B> l''ufficio od Ente cui compete l''esecuzione della fase (ad esempio una amministrazione terza nel caso in cui il movimento corrisponda ad un invio di documentazione).
<B>Procedimento:</B> l''eventuale endoprocedimento che da origine alla fase.
<B>Movimento:</B> la descrizione della fase.
<B>Note:</B> Eventuali note a corredo della fase.

Oltre ai dati sopraelencati, altre sigle possono venire visualizzate a lato di ogni movimento:
P: presenza di un parere per il movimento.
N: presenza di note.
Pr: presenza di un numero di protocollo.
[graffetta]: presenza di uno o più files allegati.
A: presenza di una autorizzazione collegata al  movimento.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATISELEZIONE.ASP',
'La scheramata consente di cercare tra le manifestazioni presenti o di creare un nuova manifestazione. Pe manifestazione si intende uno specifico mercato o una fiera (Es. "Mercato del Venerdi" o "Fiera della Patata").
Utilizzare il pulsante <b>Cerca</b> per ottenre la lista ed il dettaglio delle manifestazioni già inserite nel sistema.
Utilizzare il pulsante <b>Nuovo</b> per inserire una nuova manifestazione nel sistema.

','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATISELEZIONE.ASP',
'La schermata visualizza la lista delle manifestazioni presenti nel sistema. Per accedere ad una manifestazione, selezionarne il codice visualizzato nella prima colonna.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATISTRADARIOLISTA.ASP',
'La Schermata consente di specificare la localizzazione della manifestazione, inserendo diversi toponimi (vie, piazze, ecc.). 
<b>Nuovo:</b> consente di aggiungere un nuovo toponimo, selezionandolo dallo stradario del Comune.
Per eliminare un toponimo dall''elenco utilizzare il pulsante<img src="help/Istanze/Img/OneriDetSupButt.gif" border="0"> posto a fianco del singolo elemento.','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATOSTRADARIO.ASP',
'La schermata consente di selezionare dallo stradario un toponimo (via, piazza, corsoi, ecc.) da collegare al singolo mercato.
Selezionare <b>Cerca</b> per ricercare l''elemento nello stradario; selezionare <b>Salva </b> per inserire l''elemento selezionato nel mercato corrente.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATIDLISTA.ASP',
'La schermata mostra le informazioni relative ai posteggi della manifestazione in maniera aggregata, tramite una visualizzazione in forma di tabella, ogni cella della quale contiene le informazioni relative ad un posteggio. I posteggi vengono automaticamente numerati in ordine crescente, ma è possibile attribuire altre numerazioni alternative (es: 1a, 65B, 1pa, ecc.).
E'' possibile visualizzare solo alcuni posteggi della manifestazione, applicando i filtri presentati nella sezione "Filtra posteggi"; i filtri che è possibile utilizzare sono: indirizzo; merceologie; merceologie consentite o vietate; note dei singoli posteggi.

La parte inferiore della schermata presenta la struttura dei posteggi della manifestazione; per ogni posteggio vengono visualizzate le seguenti informazioni:
<b>Codice del posteggio:</b> (in colore rosso) è tipicamente il numero che identifica il posteggio ma può essere anche una sigla.
<b>Merceologia:</b> le merceologie consentite o vietate nel posteggio.
<b>Concessionari:</b> il titolare o i titolari delle concessioni; per uno stesso posteggio vi possono essere diversi concessionari per la mattina ed il pomeriggio, oppure per i diversi giorni della settimana in cui la manifestazione si tiene.
<b>N:</b> posizionando il mouse sopra, vengono visualizzate le eventuali note legate al posteggio (ad esempio le prescrizioni del posteggio).
<b>S:</b> posizionando il mouse sopra, viene visualizzata la storia del posteggio. La storia comprende i precedenti concessionari, oltre che l''attuale occupante che può anche essere diverso dal concessionario (ad esempio in caso di affitto d''azienda).

Per modificare i dati di un posteggio, selezionare il codice del posteggio per accederne al dettaglio.
Per modificare i dati di più di un posteggio contemporaneamente, spuntare i posteggi interessati e quindi selezionare il pulsante <B>Modifica</B>. Le modifiche saranno applicate a tutti i posteggi selezionati.
Per eliminare dalla manifestazione uno o più posteggi spuntare i posteggi interessati e quindi selezionare il pulsante <B>Cancella</B>. 
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATIUSO.ASP',
'La schermata presenta i dati di dettaglio di un singolo posteggio. 

<b>Posteggio: </b>codice del posteggio (numerico o alfanumerico).
<b>Larghezza, Lunghezza, Superficie:</b> dati dimensionali del posteggio.
<b>Tipo spazio: </b>tipologia di posteggio. Per modificare le tipologie di posteggio accedere a <i>Archivi/software/Tabelle/Fiere e mercati/Tipi spazi posteggi</i>.
<b>Via: </b> localizzazione del posteggio.
<b>Note: </b>il campo può essere utilizzato per inserire le prescrizioni del posteggio o altre note.

Per salvare le modifiche o gli inserimenti selezionare il pulsante <B>Salva</B>. 
Per eliminare dal mercato il posteggio selezionare il pulsante <B>Cancella</B>. 
Per inserire o modificare le merceologie relative al posteggio selezionare il pulsante <B>Merceolgie</B>. 
Il pulsante <B>Conti</B> ...','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATIUSOLISTA.ASP',
'La schermata consente di visualizzare o di modificare i giorni di svolgimento del mercato. Per ogni giorno è possibile attribuire più <b>Usi</b> ovvero frazioni di giorno; se ad esempio vi sono diversi concessionari per un posteggio alla mattina ed al pomeriggio del mercoledi (giorno di svolgimento del mercato) è consigliabile impostare due diversi usi, in maniera da associare ad ognuno di essi uno specifico concessionario.
per inserire un nuovo giorno ed uso utilizzare il pusante <b>Nuovo</b>.
 ','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZEINFO.ASP',
'La schermata "Informazioni dell''istanza" riporta alcuni elementi riassuntivi dell''istanza.
<b> Stato dell'' istanza:</b>  identifica lo stato attuale dell''istanza
<b>Data validità:</b> visualizza la data in cui il richiedente è autorizzato.
<b>Autorizzazioni:</b> riporta l''elenco delle autorizzazioni emanate nel corso del procedimento e legate all''istanza.

Pulsanti:
<b>Nuova concessione:</b> consente di inserire una concessione relativa al commercio su area pubblica con posteggio.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_CONCESSIONI.ASP',
'La schermata consete di registrare una concessione relativa al commercio su area pubblica con posteggio. 
Una concessione consente di assegnare il soggetto che ha presentato l''istanza con un posteggio di un determinato mercato.
La <b>revoca</b> di una concessione è un passaggio come ad esempio la vendita o l''affitto che ha la particolarità di mantenere i riferimenti della vecchia concessione, si consiglia di utilizzare una causale specifica Es. "Revoca concessione". E'' necessario ricordarsi di impostare come data scadenza della concessione la data di revoca. La concessione non risulterà più tra le concessioni attive dal giorno successivo la scadenza.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_SORTEGGI.ASP',
'La schermata consente l''accesso alle funzioni di sorteggio delle istanze ed ai sorteggi già eseguiti. 

Pulsanti:
<B>Cerca:</B> consente di cercare tra l''elenco delle estrazioni salvate nel sistema. Nella ricerca è possibile utilizzare i campi presentati nella schermata, per filtrare i risultati.
<B>Nuovo:</B> consente di creare un nuovo sorteggio utilizzando le funzioni di sorteggio casuale del sistema.','1');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_SORTEGGI.ASP',
'La schermata consente di specificare i parametri per l''esecuzione di un sorteggio e successivamente di eseguire il sorteggio stesso. 

Parametri del sorteggio
<b>Data sorteggio:</b> 
<b>Tipologia intervento:</b> consente di includere nel sorteggio solamente le pratiche caratterizzate dalla tipologia di intervento selezionata.
<b>Tipo procedura:</b> consente di includere nel sorteggio solamente le pratiche caratterizzate dalla procedura selezionata.
<b>Data movimento dal giorno / al giorno:</b> consente di includere nel sorteggio solo le pratiche avviate nell¿intervallo di tempo definito dai due campi. Nel caso in cui sia stato definito un movimento nel precedente campo, l¿intervallo si riferisce alla data di registrazione del movimento.
<b>Tipo Movimento:</b> consente di includere nel sorteggio solamente le pratiche nelle quali è stato eseguito il movimento specificato.
<b>Tipologia di ricerca del movimento:</b>consente di specificare se il movimento va ricercato tra quelli fatti ( movimenti dell''istanza ), da effettuare ( scadenzario ) o in tutti e due.
<b>Stato:</b> consente di includere nel sorteggio solo le pratiche con uno specifico stato.
<b>Percentuale:</b> la percentuale da estrarre come risultato tra le pratiche considerate.
<b>Estrazione a gruppi di n.:</b> consente di limitare il risultato dell¿estrazione ad un multiplo del numero inserito. 
<b>Esclude:</b> Esclude le istanze che hanno preso parte a precedenti estrazioni salvate.
<b>Salva:</b> salva l¿estrazione corrente.
<b>Descrizione:</b> consente di inserire una descrizione per l¿estrazione corrente.

Il pulsante <b>Avvia Sorteggio</b> avvia i sorteggio con i parametri inseriti e, nel caso sia stata spuntata l''apposita casella, salva il risultato nel sistema. ','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_SORTEGGI.ASP',
'La schermata presenta l''elenco dei sorteggi salvati nel sistema. Per visualizzare l''elenco delle pratiche estratte da un sorteggio, selezionare  il codice del sorteggi nella prima colonna. 

La colonna <b>filtri</b> consente di visualizzare un resoconto dei parametri utilizzati nel singolo sorteggio. 
La colonna <b>azioni</b>  presenta varie icone che consentono, nell¿ordine, di:
-	eliminare il sorteggio
-	esportare i risultati del sorteggio in un file di testo
-	creare una stampa per il sorteggio tramite le funzioni di documenti tipo
-	aggiungere a tutte le pratiche sorteggiate un preciso movimento, in maniera automatica

La colonna <b>Allegato</b> consente caricare un file allegato a tutte le pratiche sorteggiate. 
','2');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_SORTEGGIMOVIMENTI.ASP',
'La schermata consente di agiungere un movimento a tutte le pratiche risultato di un sorteggio. La funzione è accessibile una volta salvato il sorteggio.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CO',
'/tipibando/list.htm',
'In questa sezione è possibile cofigurare diversi modelli di Bando sui ognuno dei quali generare successivamente diverse tipologia di graduatorie.
Nel commercio su area pubblica i bandi possono venire utilizzati per la creazione delle graduatorie relative alla partecipazione alle Fiere. Tiè!
Se presenti già dei modelli di bandi la schermata visaulizza l''elenco dei modelli di bando; selezionare ... alla destra di ogni  elemento per accedere al dettaglio del singolo modello di bando.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CO',
'/tipigraduatoriet/list.htm',
'La pagina presenta i diversi modelli di graduatorie che possono essere configurati all''interno di un modello di bando. Ogni modello determina una graduatoria in base a specifici parametri. Selezionare ... alla destra di ogni modello di graduatoria per accedere al dettaglio. Per aggiungere un nuovo modello di graduatoria utilizzare il pilsante "Nuovo".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CP',
'/tipigraduatoriet/list.htm',
'La pagina presenta i diversi modelli di graduatorie che possono essere configurati all''interno di un modello di bando. Ogni modello determina una graduatoria in base a specifici parametri. Selezionare ... alla destra di ogni modello di graduatoria per accedere al dettaglio. Per aggiungere un nuovo modello di graduatoria utilizzare il pilsante "Nuovo".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CO',
'/tipigraduatoriet/view.htm',
'La pagina consente di specificare le caratteristiche di un singolo modello di graduatoria. Le informazioni rilevanti sono:
<B>Descrizione:</B> la descizione che identifica il modello di graduatoria.

Altre informazioni che possono essere specificate sono le condizioni di ammissione delle singole pratiche in graduatoria; per ogni graduatoria possono essere specificate n condizioni di ammissione, ognuna delle quali viene definita da una coppia campo - valore; solo le pratiche che rispecchiano il valore del/i campo/i specificato/i  vengono ammesse in graduatoria.
<B>Campo:</B> Sono i campi che determinano quali istanze vengono ammesse alla graduatoria (es: "domanda accettata").
<B>Valore:</B> Il valore del campo che determina l''amissione della singole istanza in grauduatoria (es: "domanda accettata" = VERO)

Il pulsante "Criteri di ordinamento" consente di specificare quali sono i parametri per il calcolo della graduatoria.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CP',
'/tipigraduatoriet/view.htm',
'La pagina consente di specificare le caratteristiche di un singolo modello di graduatoria. Le informazioni rilevanti sono:
<B>Descrizione:</B> la descizione che identifica il modello di graduatoria.

Altre informazioni che possono essere specificate sono le condizioni di ammissione delle singole pratiche in graduatoria; per ogni graduatoria possono essere specificate n condizioni di ammissione, ognuna delle quali viene definita da una coppia campo - valore; solo le pratiche che rispecchiano il valore del/i campo/i specificato/i  vengono ammesse in graduatoria.
<B>Campo:</B> Sono i campi che determinano quali istanze vengono ammesse alla graduatoria (es: "domanda accettata").
<B>Valore:</B> Il valore del campo che determina l''amissione della singole istanza in grauduatoria (es: "domanda accettata" = VERO).

Il pulsante "Criteri di ordinamento" consente di specificare quali sono i parametri per il calcolo della graduatoria.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CO',
'/tipibandocampigraduat/list.htm',
'La pagina visualizza la lista dei parametri utilizzati per la generazione della specifica graduatoria, sulla base delle istanze presentate.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CP',
'/tipibandocampigraduat/list.htm',
'La pagina visualizza la lista dei parametri utilizzati per la generazione della specifica graduatoria, sulla base delle istanze presentate.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CO',
'/mercaticonfigurazione/view.htm',
'La pagina presenta i parametri di configurazione per tutte le manifestazioni del corrente modulo. I parametri vengono utilizzare per automatizzare determinate operazioni di calcolo e di configurazione delle manifestazioni. i <b>Parametri concessioni</b> sono:
<b>Settore merceologico:</b> Tipo e dettaglio informazione che vengono utilizzare per specificare la merceologia nella istanza di domanda di partecipazione alla fiera o mercato.
<b>Causale canone di default:</b> causale di contabilità.
<b>Causale aumento di accertamento:</b> causale di contabilità.
<b>Causale diminuzione di accertamento:</b> causale di contabilità.
<b>Conto economico predefinito:</b> 
<b>Registro autorizzazioni:</b>

<b>Parametri concessioni:</b> vengono utilizzati per precompilare i dati delle nuove concessioni.

<b>Parametri estremi autorizzazione per memorizzazione presenze:</b>
Impostando correttamente gli estremi dell''autorizzazione verrà cambiata la modalità
di storicizzazione delle presenze. In questo caso le presenze non saranno storicizzate per anagrafica, ma per autorizzazione. Selezionare il modello della scheda dinamica dove sono presenti i campi che identificano gli estremi dell''autorizzazione.

<b>Parametri rateizzazioni:</b>
Consente di impostare le soglie di rateizzazione per i pagamenti','0');
