CONTENTTYPE,
HELPTEXT,
TAB) values ('CP',
'/mercaticonfigurazione/view.htm',
'La pagina presenta i parametri di configurazione per tutte le manifestazioni del corrente modulo. I parametri vengono utilizzare per automatizzare determinate operazioni di calcolo e di configurazione delle manifestazioni. i <b>Parametri concessioni</b> sono:
