<b>Parametri estremi autorizzazione per memorizzazione presenze:</b>
Impostando correttamente gli estremi dell''autorizzazione verrà cambiata la modalità
di storicizzazione delle presenze. In questo caso le presenze non saranno storicizzate per anagrafica, ma per autorizzazione. Selezionare il modello della scheda dinamica dove sono presenti i campi che identificano gli estremi dell''autorizzazione.

<b>Parametri rateizzazioni:</b>
Consente di impostare le soglie di rateizzazione per i pagamenti','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibando/list.htm',
'In questa sezione è possibile cofigurare diversi modelli di Bando per ognuno dei quali generare successivamente diverse tipologie di graduatorie.

Se presenti già dei modelli di bando, la schermata visaulizza ne l''elenco ; selezionare il pulsante "dettaglio" alla destra di ogni  elemento per accedere al dettaglio del singolo modello di bando.
Per inserire un nuovo modello di bando utilizzare il pulsante "Nuovo".
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibando/view.htm',
'La pagina riporta il detaglio di un singolo modello di bando. Le seguenti informazioni caratterizzarno uno specifico modello di bando:
<b>Descrizione: </b> descizione che identifica il modello di graduatoria.
<b>Scheda dinamica: </b>La scheda dinamica che contiene i campi utilizzati come parametri dalle diverse graduatorie che possono originare dal bando.
<b>Attivo: </b> rende il modello utilizzabile nella creazione delle graduatorie.
<b>Modelli graduatorie: </b> consente di configurare divesi modelli di graduatorie, definite da diversi parametri.
<b>Valori da distribuire: </b> consente di impostare soglie o condizioni minime di assegnazione per il bando.

Per registrare l''eventuale modifica delle informazioni selezionare il pulsante "Salva".
Il pulsante "Elimina" elimina il modello di bando e tutti i modelli di graduatoria in esso contenuti.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipigraduatoriet/list.htm',
'La pagina visualizza l''elenco dei modelli di garduatoria configurati nel sistema per uno specifico bando. Per accedere al dettaglio del singolo modello di graduatoria selezionare il pulsante "dettaglio".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipigraduatoriet/view.htm',
'La schermata consente di configurare i parametri utilizzati nella creazione di una graduatoria.
In base alla scheda dinamica utilizzata dal bando, è possibile definire le condizioni da considerare affinchè una specifica domanda prenda parte alla specifica graduatoria. inoltre è possibile definire le condizioni che determinano l''ordinamento delle pratiche in gradatoria.
Ogni condizione è rappresentata da un campo della scheda dinamica utilizzata:
<b>Campo: </b>il campo della scheda dinamica utilizzato come criterio di inclusione delle istanze nella graduatoria.
<b>Valore: </b>il valore relativo ad un campo, che determina l''inclusione nella graduatoria.
<b>Criteri di ordinamento: </b>consente di accedere ai criteri che determinano l''ordiine in graduatoria delle istanze.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibandocampigraduat/list.htm',
'La pagina riporta l''lenco delle condizioni utilizzate dalla singola graduatoria per determinare l''ordinamento delle pratiche, ordinate in base alla priorità. Per accedere alla configurazione di una singola condizione selezionare il pulsante "dettaglio". Per inserire una nuova condizione selezionare il pulsante "Nuovo".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibandocampigraduat/view.htm',
'Nella pagina è possibile modificare il dettaglio di un singolo parametro utilizato in graduatoria.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibandocampigraduat/create.htm',
'Nella pagina è possibile definire il dettaglio di un singolo parametro utilizato in graduatoria.
<b>Campo: </b>definire il campo della scheda dinamicoa da utilizzare come criterio della graduatoria.
<b>Ordinamento: </b>definire il tipo di ordinamento che determina l''ordine delle pratiche per lo specifico campo.
<b>Ordine: </b>numero d''ordine secondo cui il parametro viene considerato.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/bandi/list.htm',
'La pagina visualizza l''elenco dei bandi pubblicati. Per ogni bando possono essere generate e salvate differenti graduatorie, basati su un singolo modello di graduatoria o su diversi modelli di graduatoria.
Per accedere al dettaglio di un bando salvato, selezionare il pulsante "dettaglio".
Per inserire un nuovo bando selezionare "Nuovo".
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/bandi/view.htm',
'La pagina visualizza il dettaglio di un singolo bando, creato sulla base di un modello di bando. 
Le informazioni che caratterizzano il bando sono:
<b>Bando: </b>descrizione che identifica il bando (es: "bando partecipazione fiera di settembre 2009").
<b>Data pubblicazione e data scadenza: </b>
<b>Modello di bando: </b> modello di bando utilizzato.
<b>Albero procedimenti: </b> la voce dell''albero dei procedimenti che identifica le pratiche di richiesta partecipazione al bando.

La pagina riporta inoltre la graduatoria, o l''elenco delle graduatorie, generate e salvare nell''ambito dello specifico bando. 

Per visualizzare il risultato di una singola graduatoria selezionare il pulsante "dettaglio".
Per inserire una nuova graduatoria per il bando utilizzare il relativo pulsante in  fondo alla pagina.

','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/bandi/create.htm',
'La pagina consente di inserire un nuovo bando, creato sulla base di un modello di bando precedentemente configurato. Le informazioni che caratterizzano il bando sono:
<b>Bando: </b>descrizione che identifica il bando (es: "bando partecipazione fiera di settembre 2009").
<b>Data pubblicazione e data scadenza</b> inserire le date richieste.
<b>Modello di bando: </b>selezionare uno tra i modelli di bando configurati.
<b>Albero procedimenti: </b>selezionare la voce dell''albero dei procedimenti che identifica le pratiche di richiesta partecipazione al bando.
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/bandi/viewGraduatoria.htm',
'La pagina visualizza la denominazione ed il risultato della graduatoria, generato sulla base dei parametri configurati nel modello di graduatoria utilizzato. 
Viene riportata la lista ordinata delle istanze.
Selezionando la casella di spunta "Criteri di ordinamento", vengono visualizzati i criteri che hanno determinato l''ordinamento per ogni singola pratica.
Selezionando "Rilascia concessione" è possibile registrare nel sistema una concessione a seguito dei risultati della graduatoria.
Nella sezione "Movimento da inserire" è possibile aggiungere, alle pratiche oggetto di graduatoria, uno specifico movimento.
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/bandi/createGraduatoria.htm',
'La pagina consente di registrare una nuova graduatoria, sulla base di un modello. 
Inserire una descrizione per la graduatoria e selezionare uno dei modelli di graduatoria disponibili.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('CP',
'/tipibando/list.htm',
'Nel commercio su area pubblica i bandi possono venire utilizzati per la creazione delle graduatorie relative alla partecipazione alle Fiere. Tiè!','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/tipibando/create.htm',
'Nella creazione di un nuovo modello di bando è necessario inserire le seguenti informazioni:

<B>Descrizione:</B> Nome assegnato al modello.
<B>Scheda dinamica:</B> La scheda dinamica dell''istanza, che contiene i dati che verranno utilizzati o come parametri per la graduatoria o come criteri per l''inclusione di specifiche pratiche nella graduatoria.
<B>Attivo:</B> attiva la possibilità di utilizzare il bando per la creazione di graduatorie.

Terminato l''inserimento selezionare il pulsante "Inserisci".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATI.ASP',
'La schermata presenta le informazioni generali relative ad una manifestazione, assieme ad una serie di pulsanti, in basso nella pagina, che consentono di visualizzare o modificare le informazioni di dettaglio. I posteggi isolati (o piazze morte) vengono considerati come un mercato o una fiera e di conseguenza inseriti in questa sezione. Nel caso in cui si stia inserendo una nuova manifestazione è possibile inerire nel campo <b>Posteggi</b> il numero di posteggi: il sistema provveda a generare automaticamente i posteggi al primo salvataggio dei dati.

I campi presentati sono i seguenti:

<b>Manifestazione:</b> la denominazione della manifestazione ( mercato, fiera, gruppo di posteggi isolati o singolo posteggio isolato).
<b>Tipo manifestazione:</b> la tipologia di manifestazione.
<b>Registra assenze in contabilità:</b> se spuntato consente di registrare nella contabilità le assenze dal posteggio della manifestazione.
<b>Immagine:</b> consente di caricare un''immagine che può essere utilizzata come mappa interattiva.
<b>Note:</b> consente di registrare delle note relative alla manifestazione (esempio prescrizioni generali per il mercato).

Pulsanti:
<b>Salva:</b> registra gli inserimenti o le modifiche fatte nella presente schermata.
<b>Cancella:</b> elimina il mercato e tutte le informazioni collegate dal sistema.
<b>Localizzazione:</b> consente di specificare le vie in cui è ubicata la manifestazione.
<b>Posteggi:</b> consente di inserire, modificare e visualizzare i posteggi.
<b>Giorni:</b> consente di specificare i giorni in cui si svolge la manifestazione. Per impostare tale parametro è necessario prima configurare l''uso in <i>Archivi/software/Tabelle/Manifestazioni/Concessioni uso</i>.
<b>Conti:</b> 
<b>Calendario:</b> consente di creare il calendario annuale delle giornate in cui si tiene la manifestazione.
<b>Stampa:</b> consente la stampa di diversi documenti tra cui documenti riassuntivi sulla occupazione della manifestazione.
<b>Chiudi:</b> esce dalla schermata senza salvare le modifiche.
','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MERCATIDATTIVITAISTATLISTA.ASP',
