Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/calendariomercato/listusianni.htm',
'La schermata consente di creare il calendario annuale delle giornate in cui si tiene la manifestazione. Per ogni anno solare viene normalmente creato un singolo calendario. I calendari creati vengono visualizzati nella lista. Per ogni calendario è possibile:

