','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_RESPONSABILI.ASP',
'<b>Scheda di gestione degli operatori</b>

In  questa scheda vengono gestite tutte le informazioni degli operatori che andranno ad utilizzare SIGePro.

Le informazioni gestibili possono essere di carattere <b>informative</b> ( codice fiscale, indirizzo, e-mail, ... ) che vengono utilizzate principalmente nelle stampe dei documenti o nell''invio di mail o <b>operative</b> per la gestione del backoffice.
Le informazioni operative gestibili sono le seguenti:
<b>User Id</b>: nome utente utilizzato per accedere a SIGePro.
<b>Password</b>: password utilizzata per l''accesso a SIGePro.
<b>Scadenzario all''avvio</b>: Se il flag è spuntato, viene visualizzato lo scadenzario generale all''avvio della procedura
<b>Scadenze</b>:Se il flag è spuntato, lo scadenzario all''avvio, visualizza tutte le scadenze comprese quelle antecedenti alla data richiesta 
<b>Filtra scadenze</b>: Se il flag è spuntato, in fase di visualizzazione dello scadenzario, verranno visualizzate solamente le pratiche di competenza dell''operatore.
<b>Preavviso scadenzario</b>: E'' riferito allo scadenzario visualizzato all''avvio ed indica il numero di giorni entro i quali individuare le scadenze
<b>Modifica help on line</b>: Gli operatori con questo flag abilitato, possono personalizzare l''help che verrà visualizzato dagli altri operatori che utilizzano il software.
<b>Abilita gestione oneri</b>: Spuntando questo flag, la gestione degli oneri viene limitata ai soli operatori con il flag abilitato. Se nessun operatore ha il flag spuntato, allora tutti possono gestire gli oneri.
<b>Blocca la gestione degli oneri</b>: Spuntando questo flag viene data all''operatore la possibilità di bloccare la fase di gestione degli oneri di un''istanza. Una volta bloccata, solamente chi ha il flag spuntato può sbloccarla e renderla accedibile a tutti oppure continuare a gestire gli oneri dell''istanza. <b><i>Attenzione: se è abilitato il flag Abilita gestione oneri, le seguenti regole verranno applicate solamente a quegli operatori. Tutti gli altri non avranno la possibilità di gestire gli oneri delle istanze.</i></b>
<b>Operatore in sola lettura</b>: L''operatore in sola lettura può accedere a SIGePro in sola visualizzazione e non può inserire/modificare/cancellare alcuna informazione.
<b>Operatore disabilitato</b>: L''operatore disabilitato non può più accedere a SIGePro.
<b>Modifica numero istanza</b>: All''operatore abilitato, in fase di modifica delle informazioni dell''istanza, comparirà un bottone a fianco al numero dell''istanza per permetterne la modifica.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/gestionepresenze/list.htm',
'Per ogni giornata in cui si tiene la manifestazione è possibile registrare le occupazioni dei posteggi da parte di concessionari o spuntisti, oltre che le presenza degli spuntisti alla manifestazione. Per le fiere gli spuntisti sono considerati solo tra i soggetti che hanno fatto domanda per la fiera; per i mercati è possibile ricercare gli spuntisti su tutta l''anagrafe del sistema.','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_CONFIGURAZIONEDATITECNICI.ASP',
'<table><tr><td colspan=''2''><i><b>Ignora la parte alfanumerica</b></i></td></tr><tr><td width=''5%''></td><td width=''95%''>Questo flag, è imputabile solamente se il numero istanza è proposto in automatico ed è possibile modificarlo manualmente.
Viene utilizzato per determinare se, in fase di aggiornamento automatico del numeratore delle istanze, il sistema deve tenere conto anche della parte alfanumerica oppure ignorarla ( per parte numerica si intende la porzione di numero individuata partendo da sinistra fino al primo carattere non numerico, la restante parte va a comporre la componente alfanumerica ).
Supponendo ad esempio che il numero proposto dal sistema in fase di inserimento istanza sia 100/DIA/1 ( dove <b>100</b> è la parte numerica e <b>/DIA/1</b> è la parte alfanumerica ) e che venga cambiato manualmente dall''operatore con il numero 50/DIA/2:

<i><b>- se tale flag è spuntato:</b></i> verrà confrontata solamente la parte numerica del numero proposto dal sistema ( <b>100</b> ) con la corrispettiva parte del numero istanza imputato manualmente dall''operatore ( <b>50</b> ), ed essendo il primo più grande del secondo, il prossimo numero istanza proposto dal sistema rimarrà il <b>100/DIA/1</b>

<i><b>- se tale flag non è spuntato:</b></i> verrà effettuato, prima del confronto tra le due componenti numeriche ( con le stesse modalità descritte nel precedente punto ), il confronto tra la parte alfanumerica del numero proposto dal sistema ( <b>/DIA/1</b> ) con la corrispettiva parte del numero istanza imputato manualmente dall''operatore ( <b>/DIA/2</b> ); in questo tipo di confronto alfanumerico <b>/DIA/2</b> risulterà maggiore di <b>/DIA/1</b>, ed avendo questo confronto priorità maggiore di quello numerico, verrà aggiornato il numeratore dell''istanza ( aumentando progressivamente la componente numerica ) e il prossimo numero proposto sarà il <b>51/DIA/2</b>.
Questo flag ha validità sia che il numero derivi dall''intervento selezionato ( albero dei procedimenti ) sia che derivi dalla configurazione generale del modulo.</td></tr><tr><td colspan=''2''>  <b>Utilizzo:</b></td></tr><tr><td> </td><td>Se si intende utilizzare una numerazione progressiva su base annua ( es. 1/2009 o 1/2009/PC ) tale flag non deve essere spuntato in quanto si avrebbero dei problemi di aggiornamento automatico del progressivo al cambio dell''anno; se invece si utilizza una numerazione "fascicolare" ( es: 1/DIA/1, 1/DIA/2  dove la parte più a destra identifica che sono pratiche diverse dello stesso fascicolo <b>1/DIA/</b> ) allora va spuntato.</td></tr></table>','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'EZSITEUPLOADLITE.ASP',
'<b>Upload dei documenti</b>
In questa sezione è possibile fare l''upload di un file presente nel proprio computer, ricercare e collegare un file precedentemente caricato, acquisire il documento direttamente dal proprio scanner ( tramite il bottone ACQUISISCI ).','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'WEBTWAIN.ASP',
'<b><i>Acquisizione documenti tramite sorgente twain</i></b>
Cliccare l''immagine dello scanner per procedere con il primo passaggio di acquisizione dallo scanner. 
Una volta acquisito, il documento comparirà nel riquadro bianco presente sopra il bottone dello scanner.. 
Se il documento è come desiderato, confermare l''acquisizione tramite il tasto "OK".','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/Replica/VisualizzaReplica.aspx',
'<b>Elenco delle istanze replicate</b>

<b><i>Istanza d''origine</i></b>
E'' l''istanza dalla quale sono state copiate le seguenti informazioni: DOCUMENTI, ZONIZZAZIONE, DETTAGLI INFORMAZIONI, SCHEDE DINAMICHE, DATI CATASTALI, SOGGETTI COLLEGATI, STRADARI e PERMESSI.

<b><i>Istanze replicate</i></b>
E'' la lista delle pratiche che sono state generate a partire dai dati sopra descritti.
','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ISTANZEONERIREGULUS.ASP',
'<table border=''0'' cellpadding=''3'' cellspacing=''0''><tr class=''intestazionetabella''><td colspan=''2''>Informazioni sui pagamenti</td></tr><tr><td valign=''top''><b>Pagante</b></td><td valign=''top''>Specifica il nominativo del pagante dell''onere.Verrà visualizzato con questa struttura:<br><b>Cognome Nome (Codice Fiscale) Ragione Sociale</b></td></tr><tr><td valign=''top''><b>Causale</b></td><td valign=''top''>E''il nome della causale pagata.</td></tr><tr><td valign=''top''><b>Numero del documento</b></td><td valign=''top''>Specifica il numero del documento che è stato pagato.</td></tr><tr><td valign=''top''><b>Identificativo rata</b></td><td valign=''top''>Rappresenta il numero della rata.</td></tr><tr><td valign=''top''><b>ID ordine</b></td><td valign=''top''>Specifica l''identificativo dell''ordine di pagamento.</td></tr><tr><td valign=''top''><b>Data pagamento</b></td><td valign=''top''>Specifica la data del pagamento.</td></tr><tr><td valign=''top''><b>Metodo di pagamento</b></td><td valign=''top''>Specifica il metodo del pagamento.<br />Valori previsti:<br /><b>CCANY</b> = Carta Credito<br /><b>WALLT</b> = Portafoglio elettronico - wallet<br /><b>RIDOL</b> = RID On-line<br /><b>CMAST</b> = Carta MasterCard<br /><b>CVISA</b> = Carta VISA<br /><b>CAMEX</b> = Carta AmericanExpress <br /><b>CDINR</b> = Carta Diners <br /><b>BLTPT</b> = Bollettino postale<br />...</td></tr><tr><td valign=''top''><b>Sistema di pagamento</b></td><td valign=''top''>Specifica il sistema del pagamento.<br />Valori previsti:<br /><b>BPASS</b> = BankPass <br /><b>RID</b> = RID On-line <br /><b>POSTA</b> = Pagamento in posta<br />...</td></tr><tr><td valign=''top''><b>Canale riscossione</b></td><td valign=''top''>Specifica il canale di riscossione.<br />Valori previsti: <br /><b>WEB</b> = pagamento tramite portale web <br />...</td></tr><tr><td valign=''top''><b>Tipo pagamento</b></td><td valign=''top''>Specifica il tipo di pagamento. <br />Valori previsti: <br />- pagamento di un documento registrato<br />- pagamento spontaneo</td></tr><tr><td valign=''top''><b>Importo dovuto</b></td><td valign=''top''>Specifica l''importo dell''onere senza commissioni.</td></tr><tr><td valign=''top''><b>Commisione</b></td><td valign=''top''>Specifica il valore della commissione.</td></tr><tr><td valign=''top''><b>Totale pagato</b></td><td valign=''top''>Specifica l''importo totale pagato comprensivo di commissione.</td></tr></table>','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_TIPOLOGIACAUSALIONERI.ASP',
'<table border=''0'' cellpadding=''3'' cellspacing=''0''><tr class=''intestazionetabella''><td colspan=''2''>Causali Oneri</td></tr><tr><td valign=''top''><b>Raggruppamento</b></td><td valign=''top''>Specifica se la causale di onere fa parte di un raggruppamento ( ad esempio, le  causali <b>Urbanizzazione Primaria</b> e <b>Urbanizzazione Secondaria</b> potrebbero appartenere allo stesso raggruppamento <b>Oneri di Urbanizzazione</b></td></tr><tr><td valign=''top''><b>Causale</b></td><td valign=''top''>E''il nome della causale</td></tr><tr><td valign=''top''><b>Codice causale PEOPLE</b></td><td valign=''top''>Compare solamente se il sistema è integrato con PEOPLE ed indica il codice della corrispondente causale in PEOPLE</td></tr><tr><td valign=''top''><b>Ordinamento</b></td><td valign=''top''>Quando viene mostrata la lista delle causali per l''inserimento di un onere in un''istanza, viene utilizzato questo parametro per decidere in che ordine mostrare le causali.<br>A parità di ordinamento viene utilizzato quello alfabetico</td></tr><tr><td valign=''top''><b>Invia causale al sistema di pagamento</b></td><td valign=''top''>Questa opzione compare solamente se si è integrati con un sistema di pagamenti ( ad esempio REGULUS ). Stabilisce se le scadenze di questa causale devono essere notificate o meno al sistema di pagamento attivato</td></tr><tr><td valign=''top''><b>Associa la causale ad un endoprocedimento</b></td><td valign=''top''>Se selezionato, in fase di gestione oneri nell''istanza, sarà possibile associare l''onere ad un endoprocedimento e quindi sarà possibile gestire gli oneri in entrata ed in uscita. Gli oneri in entrata sono quelli che vengono pagati dal richiedente al comune, mentre gli oneri in uscita sono quelli che il comune deve pagare ad amministrazioni esterne.</td></tr><tr><td valign=''top''><b>Disabilita</b></td><td valign=''top''>Se selezionato, non rende visibile questa causale in fase di inserimento di un onere.</td></tr></table>','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/foarconfigurazione/create.htm',
'<strong>Configurazione area riservata</strong><p>I dati visualizzati rappresentano i valori relativi al modulo selezionato.<br/>Se non sono presenti tali valori per il modulo, verranno visualizzati i dati generici per tutti i FrontOffice.<br/>Sarà necessario salvare i dati per il modulo selezionato.<br/>Nel caso in cui in entrambi i moduli non è presente una configurazione, è necessario inserirla una nuova.<br/></p><table border=''0'' cellpadding=''2'' cellspacing=''0''><tr class=''intestazionetabella''><td valign=''top'' colspan=''2''>Valori di configurazione</td></tr><tr><td valign=''top''><b>Stato iniziale istanza</b></td><td valign=''top''>Stato iniziale in cui si deve trovare un''istanza al momento dell''inserimento.(Nel caso di tutti i FrontOffice questo campo non verrà visualizzato)</td></tr><tr><td valign=''top''><b>Intestazione dettaglio visura</b></td><td valign=''top''>Definisce il messaggio visualizzato nell''intestazione della pagina che riepiloga l''istanza on-line appena inviata.</td></tr><tr><td valign=''top''><b>Messaggio invio fallito</b></td><td valign=''top''>Messaggio da visualizzare nel frontoffice nel caso in cui la creazione dell''istanza fallisca.<br/>Se il campo è vuoto verrà mostrato un messaggio di default.<br/><b>Esempio:</b><br/><i>La pratica è stata inviata allo sportello tuttavia non è stato possibile effettuarne l''elaborazione.<br/>La preghiamo di contattare telefonicamente lo sportello al numero xxxx-xxxxxx negli orari: Mattino - Lunedì dalle 11.00 - 13.00<br/>Pomeriggio - Martedì,Giovedì dalle 15.30 - 17.30<br/>Fornendo all''operatore il numero pratica riportato qui sotto Numero pratica: I921_CE_XXXXXXXXXXXXXXXX_0060</i></td></tr><tr><td valign=''top''><b>Certificato di invio tramite firma digitale</b></td><td valign=''top''>Documento utilizzato come certificato di invio tramite firma digitale.Il documento deve essere un file RTF che deve contenere codice XSL per la compilazione.</td></tr><tr><td valign=''top''><b>Certificato di invio tramite sottoscrizione</b></td><td valign=''top''>Documento utilizzato come certificato di invio tramite sottoscrizione.Il documento deve essere un file RTF che deve contenere codice XSL per la compilazione.</td></tr></table>','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_MENU.ASP',
'Nel campo "Ref" è possibile inserire espressioni javascript per realizzare ad esempio pagine che si aprono in popup.<br />
Per fare questo è necessario iniziare l''espressione con il testo "javascript:" oppure "js:"<br>
<br>
Ad esempio rer il marketing territoriale della Costiera Amalfitana in cui era necessario visualizzare il dettaglio della scheda di marketing relativa al comune è stato utilizzato il seguente codice:<br />
    js:window.open(''http://frontoffice.sigepro.it/mktgcostiera/comune.asp?codicepagina=8'',''p'',''width=970,height=700,scrollbars=1,resizable=1'');','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Istanze/Replica/CreaReplica.aspx',
'<b>Replica dell''istanza</b>
In questa sezione è possibile creare nuove istanze a partire da un''istanza d''origine.
E'' possibile selezionare più Tipologie di intervento tramite il bottone "AGGIUNGI FILTRO".
Una volta selezionati gli interventi desiderati, avviare la replica tramite il bottone "REPLICA".

Le informazioni che verranno replicate sono tutte quelle che compaiono nella scheda dell''istanza, fatta eccezione per:
<B>NUMERO ISTANZA:</B> Verrà ricalcolato in base all''intervento scelto
<B>INTERVENTO:</B> Viene selezionato dall''operatore
<B>PROCEDURA:</B> Verrà ricalcolata in base all''intervento scelto
<B>RESPONSABILE DEL PROCEDIMENTO:</B> Verrà ricalcolato in base all''intervento scelto

Oltre alle informazioni presenti nella prima scheda, verranno replicate anche le seguenti informazioni:
<b>DOCUMENTI DELL''ISTANZA</b>
<b>ZONIZZAZIONI</b>
<b>DETTAGLI INFORMAZIONI</b>
<b>SCHEDE DINAMICHE DELL''ISTANZA</b>
<b>DATI CATASTALI</b>
<b>SOGGETTI COLLEGATI</b>
<b>PERMESSI</b>
<b>LOCALIZZAZIONI</b>','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_RICHIEDENTIPG.ASP',
'<b>Altri dati</b>
<u><i>Tipo Invio F.O.</i></u>
Questo parametro è visibile solamente solamente per i tecnici e permette di stabilire la modalità di invio nella sezione dell''area riservata del front-office. Può assumere i seguenti valori:
- Invio diretto della pratica ( default ): La pratica presentata dal tecnico nel front-office può essere inviata direttamente al back-office.
- Passaggio della pratica al richiedente: La pratica presentata dal tecnico nel front-office non viene inviata al back-office ma al richiedente della pratica il quale provvederà poi a firmarla digitalmente ed inviarla al nack-office.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_RICHIEDENTIPF.ASP',
'<TABLE WIDTH=''100%'' BORDER=0 CELLPADDING=0 CELLSPACING=0><TR CLASS=''INTESTAZIONETABELLA''><TD COLSPAN=''2''>Altri dati</TD></TR><TR><TD COLSPAN=''2''><u><i>Invio Istanza</i></u></TD></TR><TR><TD WIDTH=''25px''></TD><TD>Questo parametro è visibile solamente solamente per i tecnici e permette di stabilire la modalità di invio nella sezione dell''area riservata del front-office. Può assumere i seguenti valori:
- Invio diretto della pratica ( default ): La pratica presentata dal tecnico nel front-office può essere inviata direttamente al back-office.
- Passaggio della pratica al richiedente: La pratica presentata dal tecnico nel front-office non viene inviata al back-office ma al richiedente della pratica il quale provvederà poi a firmarla digitalmente ed inviarla al nack-office.</TD></TR></TABLE>','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_ALBEROPROCDOCUMENTI.ASP',
'<TABLE WIDTH=''100%'' BORDER=0><TR CLASS=''INTESTAZIONETABELLA''><TD COLSPAN=''2''>GESTIONE DOCUMENTI</TD></TR><TR><TD COLSPAN=''2''><I><b>Ordine</b></I></TD></TR><TR><TD WIDTH=''25PX''></TD><TD>Stabilisce l''ordinamento in cui vengono visualizzati i documenti nel front-office. Non è visibile in fase di inserimento ma solamente in fase di modifica</TD></TR><TR><TD COLSPAN=''2''><I><b>Modello domanda</b></I></TD></TR><TR><TD></TD><TD>Se il flag è spuntato, l''allegato rappresenta il modulo principale della domanda. Non è possibile contrassegnare come tale più di un allegato per ogni singola voce dell''albero. Compare solamente se è spuntato il flag <i><b>Pubblica</b></i></TD></TR></TD></TR><tr><td colspan=''2''><I><b>Richiede firma</b></I></td></tr><tr><td></td><td>Se spuntato, per poter completare la presentazione della domanda on-line, il soggetto interessato dovrà firmare digitalmente tale documento.</td></tr><tr><td colspan=''2''><I><b>Tipo download</b></I></td></tr><tr><td></td><td>Indica i possibili formati in cui verrà reso disponibile il documento dal Front-Office. E'' possibile selezionare contemporaneamente più formati tenendo premuto il tasto <b>CTRL</b></td></tr><tr><td colspan=''2''><I><b>Categoria</b></I></td></tr><tr><td></td><td>Serve ad assegnare una classificazione ai documenti. Sia nel front-office che nei documenti dell''istanza, se c''è almeno un allegato con una categoria impostata, la lista dei documenti verrà mostrata suddivisa in base alle categorie ed eventuali documenti non assegnati verranno mostrati nella sezione "Altri documenti". Se nessun documento della lista ha la categoria assegnata allora la visualizzazione rimane quella classica.</td></tr></TABLE>','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'CL_TIPISOGGETTO.ASP',
'<table border=''0'' width=''100%''><tr class="intestazionetabella"><td colspan="2">Dati per il Front Office</td></tr><tr class="row0"><td valign=''top''><b><i>Utilizzo</i></b></td><td>La tipologia di soggetto può essere utilizzata solo sulla domanda on-line del front office, solo nel backoffice o su entrambe i moduli.</td></tr><tr class="row1"><td valign=''top''><b><i>Tipologia anagrafe</i></b></td><td>Se ''Persona Fisica'', nella domanda on-line, l''anagrafica associata a questa tipologia può essere solo una persona fisica. Viceversa se ''Persona Giuridica''.</td></tr><tr class="row0"><td valign=''top''><b><i>Tipologia del soggetto collegato</i></b></td><td>Nella domanda on-line:
l''anagrafica associata a ''Richiedente'' verrà inserita sul campo richiedente dell''istanza.
l''anagrafica associata a ''Azienda'' verrà inserita sul campo azienda richiedente dell''istanza.
l''anagrafica associata a ''Tecnico'' verrà inserita sul campo tecnico dell''istanza.
se non specificato verrà inserita nei soggetti collegati dell''istanza.</td></tr><tr class="row1"><td valign=''top''><b><i>Obbligatorio</i></b></td><td>Spuntare se nella domanda on-line deve essere presente almeno un''anagrafica associata alla tipologia obbligatoria, altrimenti la domanda non potra essere presentata</td></tr><tr class="row0"><td valign=''top''><b><i>Albo professionale</i></b></td><td>Spuntare il flag, se nella compilazione della domanda on-line, relativamente alle anagrafiche, deve essere data la possibilità di inserire i dati dell''albo professionale ( Albo, Numero, Provincia)</td></tr><tr class="row1"><td valign=''top''><b><i>Specifica descrizione</i></b></td><td>Questo flag va spuntato nel caso si voglia introdurre una descrizione generica del tipo soggetto. Dopo aver selezionato questa tipologia di soggetto, comparirà una casella di testo libero in cui specificare manualmente la tipologia.</td></tr></table>','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/stp/pannellocontrollo.htm',
'La funzionalità <b>"Pannello controllo"</b> serve per gestire le chiamate all''infrastruttura CART.
E'' composto di due pannelli principali visibili o meno a seconda delle sezioni in cui ci si trova:
<a name="elenco"></a>
<ol>
<li><a href="#controllo">Controllo messaggi da regione</a></li>
<li><a href="#richieste">Richieste del Suap</a></li>
</ol>
<fieldset><legend><b><a name="controllo" href="#elenco">Controllo messaggi da regione</a></b></legend>
Serve per verificare se sono pervenuti all''ente delle risposte a richieste di invio dizionario, invio scheda, ecc...
Sono presenti una serie di comandi che permettono di verificare l''avvenuta ricezione di messaggi.
I pulsanti <b>CONTROLLO MESSAGGI</b> a fianco di una funzionalità specifica, ad esempio <i>Invio dizionario</i> verificano la presenza di messaggi per quel tipo di evento.
Se dopo l''esecuzione dovessero essere presenti dei messaggi allora comparirànno a fianco del pulsante che si è attivato altri due pulsanti <b>ELABORA</b> e <b>CANCELLA</b>. 
Il primo permette di elaborare l''informazione ricevuta. Il secondo elimina il messaggio ricevuto senza elaborarlo.
Comunque ad elaborazione avvenuta con successo il messaggio viene cancellato.
I pulsanti in basso della scheda permettono di eseguire in modo cumulativo le richieste.
in particolare:
<b>"CONTROLLA TUTTI I MESSAGGI"</b> effettua la chiamata a tutti i messaggi per i servizi elencati.
<b>"CANCELLA TUTTI I MESSAGGI"</b> effettua la chiamata alla cancellazione di tutti i messaggi inviati all''ente.

</fieldset>
<fieldset><legend><b><a name="richieste"  href="#elenco">Richieste del Suap</a></b></legend>
Questo pannello serve per effettuare delle richieste da parte dell''ente verso il CART.
sono disponibil due opzioni:
<ol>
<li>INVIO DIZIONARIO
La chiamata alla funzionalità <u>"INVIO DIZIONARIO"</u>
notificherà al sistema CART che si intende ricevere una copia aggiornata del dizionario. Una volta eseguito il comando si dovrà controllare la ricevuta della richiesta dal pannello<u>"Controllo messaggi da regione"</u>
</li>
<li>INVIO SCHEDA
La chiamata alla funzionalità <u>"INVIO SCHEDA"</u> notificherà al sistema CART che si intende ricevere
la scheda di spiegazione per l''endo selezionato. Una volta eseguito il comando si dovrà controllare la ricevuta della richiesta dal pannello <u>"Controllo messaggi da regione"</u>. Se si sceglie l''opzione "Disponibilità" si intende verificare 
se la scheda dell''endo è stata informatizzata nel sistema CART. Se si sceglie l''opzione "Invio" si intende 
ichiedere il vero e proprio invio della scheda di spiegazione.</li>
</ol>

</fieldset>


','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/messaggicfg/view.htm',
'<strong>Configurazione del servizio di messaggistica</strong><p>I dati visualizzati rappresentano i valori relativi al modulo selezionato.<br/>Se non sono presenti tali valori, verranno visualizzati i dati generici per tutti i FrontOffice.<br/>Sarà necessario salvare i dati per il modulo selezionato.<br/>Nel caso in cui in entrambi i moduli non è presente una configurazione, allora verranno visualizzati i messaggi di base. E'' possibile selezionare il contesto dei messaggi di base.<br/></p><table border=''0'' cellpadding=''2'' cellspacing=''0''><tr class=''intestazionetabella''><td valign=''top'' colspan=''2''>Valori di configurazione</td></tr><tr><td valign=''top''><b>Contesto</b></td><td valign=''top''>Rappresenta il contesto del messaggio.Identificano i messaggi di base.</td></tr><tr><td valign=''top''><b>Oggetto</b></td><td valign=''top''>Oggetto del messaggio, si possono inserire espressioni xsl per generare dinamicamente l''output.</td></tr><tr><td valign=''top''><b>Corpo</b></td><td valign=''top''>Corpo del messaggio, si possono inserire espressioni xsl per generare dinamicamente l''output.</td></tr><tr><td valign=''top''><b>Invio soggetti</b></td><td valign=''top''>Identifica i soggetti a cui va inviato il messaggio.</td></tr><tr><td valign=''top''><b>Tipo di invio</b></td><td valign=''top''>Identifica come deve essere inviato il messaggio.</td></tr></table>','0');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'~/Archivi/DatiDinamici/Dyn2Campi.aspx',
'Per i dettagli sulla configurazione dei campi dinamici vedere il <a href="help/Archivi/Docs/CampiDinamici.doc">documento allegato</a>.','3');
Insert Into HELPBASE (SOFTWARE,
CONTENTTYPE,
HELPTEXT,
TAB) values ('TT',
'/foarconfigurazione/view.htm',
'<strong>Configurazione del Frontoffice</strong><p>I dati visualizzati rappresentano i valori relativi al modulo selezionato.<br/>Se non sono presenti tali valori per il modulo, verranno visualizzati i dati generici per tutti i FrontOffice.<br/>Sarà necessario salvare i dati per il modulo selezionato.<br/>Nel caso in cui in entrambi i moduli non è presente una configurazione, è necessario inserirla una nuova.<br/></p><table border=''0'' cellpadding=''2'' cellspacing=''0''><tr class=''intestazionetabella''><td valign=''top'' colspan=''2''>Valori di configurazione</td></tr><tr><td valign=''top''><b>Stato iniziale istanza</b></td><td valign=''top''>Stato iniziale in cui si deve trovare un''istanza al momento dell''inserimento.(Nel caso di tutti i FrontOffice questo campo non verrà visualizzato)</td></tr><tr><td valign=''top''><b>Intestazione dettaglio visura</b></td><td valign=''top''>Definisce il messaggio visualizzato nell''intestazione della pagina che riepiloga l''istanza on-line appena inviata che è la stessa della visura.</td></tr><tr><td valign=''top''><b>Messaggio invio fallito</b></td><td valign=''top''>Messaggio da visualizzare nel frontoffice nel caso in cui la creazione dell''istanza fallisca.</td></tr><tr><td valign=''top''><b>Certificato di invio tramite firma digitale</b></td><td valign=''top''>Documento utilizzato come certificato di invio tramite firma digitale.Il documento deve essere un file RTF che deve contenere codice XSL per la compilazione.</td></tr><tr><td valign=''top''><b>Certificato di invio tramite sottoscrizione</b></td><td valign=''top''>Documento utilizzato come certificato di invio tramite sottoscrizione.Il documento deve essere un file RTF che deve contenere codice XSL per la compilazione.</td></tr></table>','0');
