Delete From TASKBASE;
Insert Into TASKBASE (TASK,
DESCRIZIONE) values ('SORTEGGI',
'Operazione che permette di sorteggiare istanze. E'' possibile vedere la voce di menù Utilità/Modulo software/Sorteggi pratiche per effettuare l''operazione in modalità manuale.');
Delete From TASKPARAMETRIBASE;
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'ARCHIVIO PRATICHE',
'E'' il codice della tipologia di archivio a cui devono appartenere le istanze da estrarre',
'21');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'SOFTWARE',
'E'' il modulo sofrware sul quale effettuare il sorteggio.','2');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'TIPO INTERVENTO',
'Voce dell''albero dei procedimenti da sorteggiare, 
se non viene specificata verranno sorteggiate tutte le voci dell''albero che non hanno la voce "Escludi dal sorteggi" impostata.
Possono essere impostate più voci dell''albero, separando i relativi codici tramite ","','3');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'GRUPPI',
'Se specificato l''estrazione avviene a gruppi di istanze; ad E. ogni 10 istanze estrai il 20%, le istanze che non totalizzano un gruppo (in questo esempio 10) non prenderanno parte all''estrazione.',
'11');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'PERCENTUALE',
'E'' la percentuale delle istanze che devono essere sorteggiate. Se non speficicata viene utilizzato il 100%.',
'10');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'STATO',
'Indica lo stato delle istanze che devono essere selezionate. Può contenere una lista di stati separati da virgola Es. AT,CP oppure i valori 0=tutti gli stati attivi; -1=tutti gli stati chiusi negativi; 1=tutti gli stati chiusi positivi.','9');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'ESITO',
'Nel caso venga specificato il ''TIPO MOVIMENTO'' è l''esito del movimento. 1=positivo;0=Negativo.','8');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'ALLA DATA',
'E'' la data fino alla quale sorteggiare le istanze, fa riferimento alla data presentazione della domanda. Se non specificata prende la data dell''esecuzione.','7');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'DALLA DATA',
'E'' la data dalla quale sorteggiare le istanze, fa riferimento alla data presentazione della domanda. Se non specificata viene utilizzata la data dell''ultima estrazione effettuata.','6');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
DESCRIZIONE,
ORDINE) values ('SORTEGGI',
'TIPO MOVIMENTO',
'Se impostato verranno sorteggiate le istanze che hanno il movimento eseguito (verde nell''elaborazione).','5');
Insert Into TASKPARAMETRIBASE (TASK,
PARAMETRO,
