Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('AUTENTICAZIONE_LDAP',
'Se attiva, l''accesso a SIGePro sarà gestito da LDAP. Accesso tramite utenti di dominio. Ogni utente per accedere deve essere presente nel dominio e in SIGePro, la passowrd di accesso utilizzata sarà quella di dominio. La verticalizzazione è valida se il tipo di login non è con la combo, vedi la voce "Tipo Login" del menù CONFIGURAZIONE BACKOFFICE.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
