'Visualizza l''albero creato per gestire le esigenze dell''Ater, se non flaggato sarà visualizzato l''albero classico.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('PROT_CLASS_RESPONSABILI',
