Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('LINKSTAMPEAGGIUNTIVE',
'Se la verticalizzazione è attivata compariranno altre opzioni di stampa ( configurabili tramite i parametri di questa verticalizzazione ) dopo il click del bottone "STAMPA" presente nella scheda principale delle istanze.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('HELPBASE',
'Se = 1 verrà abilitata la possibilità di scrivere l''help di base nelle varie pagine di SIGePro utilizzando il tasto Help verde posto a destra delle pagine. Attenzione!!! Questa funzionalità va attivata solo da personale In.I.T.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('SIT_CTC',
'Se 1 indica che il sit CTC è attivo.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('BASEURL',
'Se 1 allora nei parametri può essere specificato l''url dell''applicazione ASPNET ASPNETURL(che verrà utilizzata per invocare le pagine aspx dalle pagine asp) e l''url dell''applicazione asp ASPURL che verrà utlizzato dall''applicazione aspnet per invocare le pagine asp. Quando specificato sostituisce i parametri ASPNET del webconfig e l''application("AspNetBASEURL") dell''applicazione asp.Può essere utilizzato per le installazioni in https.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('FILESYSTEM',
'Attenzione!!! Questa funzionalità va attivata solo da personale esperto di In.I.T.. Se attivata, tutti i documenti di SIGePro verranno salvati su disco e non più su database. Dopo aver attivato questa funzionalità bisogna trasferire su disco tutti gli oggetti attualmente presenti su DB, utilizzando l''utility "SpostaOggettiSuSharedPath.exe" o dalla voce di menù "utilità/Spostamento oggetti su file system". L''attivazione è valida solo per il software TT.');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
