Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('EXPORT_SCHEDA_BANDI_RER',
'Se attivato, in fondo alla lista delle istanze mostra la voce Export bandi RER che esporta i dati delle istanze visualizzate in un formato di testo con valori separati da virgola. Il tracciato è specifico della regione');
Insert Into VERTICALIZZAZIONIBASE (MODULO,
DESCRIZIONE) values ('GEST_CANCELLAZIONI',
