'PROTOCOLLOGENERALE',
'Se S significa che SIGePro è integrato con un protocollo generale unico nel comune e quindi negli xml di comunicazione tra NLA e STC i tag NUMEROPROTOCOLLOGENERALE e DATAPROTOCOLLOGENERALE verranno compilati con il protocollo dell''istanza. Se N o non presente significa che SIGePro non è integrato con nessun protocollo o ha un protocollo di direzione e quindi non deve passare i tag di riferimento al protocollo generale. ');
